/* 运行平台：原生壳（iOS/Android）注入；网页打开时回落 web */
let PLAT = (typeof window.__PLATFORM__ === "string" && window.__PLATFORM__) || "web";
function platName(){ return PLAT==="android" ? "Android 版" : PLAT==="ios" ? "iOS 版" : "Web 版"; }

let DB = { pool:null, charts:null, library:null, artists:null, mv:null, live:false };

const DB_NAMES = ["pool","charts","library","artists","mv","hero","categories","streams","lyrics","comments"];
// ★ 2026-10-06 图片沉淀：采集器把头像/KV/封面下载成**我们自己的 WebP**（data/assets/）。
//   这三份是可选的「锦上添花」——拿不到就用上游 URL 兜底，绝不因为缺它而白屏。
const ASSET_NAMES = ["av","kv","cv"];

/* 本地资源优先：assets/<kind>.json 的 map 里命中就用我们自己的图，没命中回落远程 URL。
   为什么这样做：上游（QQ gtimg / 网易 126）一改域名或加防盗链，头像+KV+封面会**同时白屏**；
   图存在自己这儿，上游怎么死都跟我无关 —— 这就是「沉淀」。 */
function assetURL(kind, key, fallback){
  const m = DB["as_"+kind];
  const rel = m && key && m[key];
  return rel ? (ASSETBASE + rel) : (fallback||"");
}

/* ★★ 图片的「节点回落」（2026-10-06 三测定案）：
   <script> 能 await 重试（见 loadScript），但 <img> 不能 —— 浏览器自己发请求、自己失败。
   所以用**全局捕获阶段的 error 事件**接住每一张加载失败的图，把它的 jsDelivr 节点换成
   下一档再试。覆盖 App 里所有图（封面/头像/KV/榜单），一处注册、全站生效。
   ★ 只轮换「我们自己 CDN 的图」；上游图（gtimg / 126）和包内相对路径不含节点前缀，
     cdnAlt 原样返回 → 不动，避免把兜底 URL 也改坏（原则：宁可慢，不能错）。
   ★ 每张图最多换到最后一档就停，绝不来回跳（防死循环 / 防抖）。 */
document.addEventListener("error", function(ev){
  const el = ev.target;
  if(!el || el.tagName !== "IMG") return;
  const cur = el.getAttribute("src") || "";
  for(let i=0;i<CDN_NODES.length;i++){
    if(cur.indexOf(CDN_NODES[i])===0){
      if(i+1 >= CDN_NODES.length){
        /* ★ 2026-10-10 四档节点全试完：若这是**图片分仓**的 URL，再回落到主仓旧路径试一遍
           （分仓刚建/刚清空、或某个仓被 GitHub 限流时，老资产仍在主仓 HEAD 里有副本）。
           只跳一次（repoHop 标记），不来回摆 —— 与节点轮换同一条纪律：宁可慢，不能抖。 */
        if(el.dataset.repoHop !== "1" && cur.indexOf(ASSET_REPOS[0]) >= 0){
          try{ el.dataset.repoHop = "1"; }catch(e){}
          el.src = cdnAlt(cur.replace(ASSET_REPOS[0], ASSET_REPOS[1]), 0);
        }
        return;                                     // 已是最后一档 → 交给上游 URL 兜底
      }
      const nx = cdnAlt(cur, i+1);
      if(nx === cur) return;
      try{ el.dataset.cdnHop = String(i+1); }catch(e){}
      el.src = nx;
      return;
    }
  }
}, true);

/* ★★ 2026-10-06 关键修复：歌曲/曲库封面也要走我们自己的图。
   事故：采集器早就把 5473 张曲库封面下载成 WebP 了，但**端上一次都没查过** ——
   封面全在直接读 s.cov（上游 gtimg/126 的 URL）。上游一加防盗链，
   歌库/播放页/歌词页/锁屏封面会**整片白图**，等于「沉淀」白做了。
   键必须与采集器 localize.py 的 _js_skey 逐字符一致（norm + slice 40/30），
   两边任何一边改了，另一边必须同步 —— 这是唯一契约。 */
function songCover(s, fallback){
  if(!s) return fallback||"";
  const k = skey(s.t, s.s);
  return assetURL("cv", k, s.cov || fallback || "");
}
/* 榜单/歌库的原始行（字段名不是 t/s）也能用：仍走 skey 建键 */
function songCoverRaw(title, singer, cov, fallback){
  return assetURL("cv", skey(title, singer), cov || fallback || "");
}

/* ★★ 图片索引加载 —— 必须走 <script> 注入，**不能**走 fetch。
   事故：采集器把几万张封面下载成我们自己的 WebP 了，但索引只给了 assets/<kind>.json，
   而端上是 file:// 页面 —— WebView 拦 fetch/XHR（见本文件「曲库目录」一节），
   fetch 永远拿不到索引 → assetURL 查不到文件名 → 所有封面回落上游 URL。
   「图下好了、端上认不出」= 沉淀白做。这就是那个根因。
   做法与曲库分块完全同构（已验证可行）：
     ① 包内 assets-<kind>.js（随包内置，离线可用）
     ② CDN 的 assets/<kind>.js（有网时热更新）
   两条都用 loadScript 注入，file:// 下 <script> 子资源**不被拦**。 */
let _assetsLoaded = false;
async function loadAssetsIndex(){
  if(_assetsLoaded) return;
  _assetsLoaded = true;
  for(const k of ASSET_NAMES){
    if(DB["assets_"+k] && DB["assets_"+k].map) continue;
    if(typeof loadScript!=="function") break;
    const g = "__DWG_ASSETS_" + k.toUpperCase();
    // ② 图片分仓（dwg-assets）同名文件：@main（新图最迟 12h 出现，期间查不到就回落上游 URL）
    // ③ 主仓旧路径：老资产副本 / 分仓故障时的兜底
    const srcs = [resURL("assets-"+k+".js"), ASSETBASE + k + ".js", CDN_DYN + "assets/" + k + ".js"];
    for(const s of srcs){
      try{ window[g]=null; }catch(e){}
      let ok=false;
      try{ ok = await loadScript(s, 12000); }catch(e){ ok=false; }
      if(!ok) continue;
      let v=null;
      try{ v = window[g]; }catch(e){}
      if(v && v.map){ DB["assets_"+k]=v; console.log("[DWG] 图片索引已加载 "+k+"："+Object.keys(v.map).length+" 条"); break; }
    }
  }
  /* 灌进 DB.as_*（assetURL 查的就是它）。拿不到的类保持 {}，assetURL 自动回落远程。 */
  ASSET_NAMES.forEach(k=>{ DB["as_"+k] = (DB["assets_"+k] && DB["assets_"+k].map) || DB["as_"+k] || {}; });
}

/* 把一份数据装载进 DB 并刷新外壳（同步） */
function applyBundle(out, live){
  Object.assign(DB, out);
  DB.live = !!live;
  // 真播放：可播直链 / 歌词 / 评论 —— 统一用「归一化(歌名)|归一化(歌手)」索引
  DB.st  = (DB.streams  && DB.streams.map)  || {};
  DB.lyr = (DB.lyrics   && DB.lyrics.map)   || {};
  DB.cmt = (DB.comments && DB.comments.map) || {};
  // 图片沉淀索引：kind → {键: 相对路径}（拿不到就空对象，全部回落远程 URL）
  ASSET_NAMES.forEach(k=>{ DB["as_"+k] = (DB["assets_"+k] && DB["assets_"+k].map) || {}; });
  // 试源顺序：云端探测失效时（机房 IP 地域风控）回落默认序，App 永远有可用的试源链
  DB.order = (DB.pool && Array.isArray(DB.pool.order) && DB.pool.order.length) ? DB.pool.order : ["wy","migu","bili"];
  // 归一化：统一歌曲数据结构
  DB.songs = (DB.library?.songs||[]).map(s=>({t:s.t,s:s.s,a:s.a||"",cov:s.cov||"",dur:s.dur||0,hue:s.hue,src:"lib"}));
  DB.artistList = DB.artists?.artists||[];
  // 全部歌手页：按拼音首字母分组（A→Z，数字/英文归 #），供字母索引跳转
  DB.artistAZ = (()=>{
    const buckets={};
    (DB.artistList||[]).forEach(a=>{
      const k=(a.py||"#").toUpperCase();
      (buckets[k]=buckets[k]||[]).push(a);
    });
    const keys=Object.keys(buckets).sort((x,y)=>(x==="#"?-1:y==="#"?1:x.localeCompare(y,"en")));
    return keys.map(k=>({letter:k,items:buckets[k]}));
  })();
  DB.charts = DB.charts||{lists:[],hotkeys:[]};
  DB.heroList = (DB.hero?.items||[]).map(s=>({t:s.t,s:s.s,a:s.a||"",cov:s.cov||"",dur:durs(s.dur),hue:s.hue}));
  DB.cats = DB.categories||{groups:[]};
  DB._all = null;   // 全库检索缓存失效，下次搜索重建
  paintFooter(); buildTabs();
}
function snapBundle(){ const o={}; DB_NAMES.forEach(n=>o[n]=SNAP[n]); return o; }

/* ★★★ 2026-10-06 重写：从 fetch 改成 <script> 注入（这是「数据能否热更到手机」的命门）。
   为什么非改不可：
     · iOS 的 WebView 在 file:// 页面下**拦截 fetch / XHR，只放行 <script> / <img>**；
       原来这里用 fetch 拉 data/<n>.json → 在 iOS 上必然全部失败 → refreshLive 永远 false
       → **云端数据热更不上去，只能靠重新出包**（这才是"采集好的东西用不上"的真根因）。
     · 云端现在由 tools/mkdata_js.py 同时产出 data/<n>.js：
         window.__DWG_DB_POOL={...};
       <script> 注入即可拿到，iOS / 安卓 / 网页三端一套代码。
   ★ 只拉「小且会变」的 6 个（合计约 645KB）：曲库池 / 榜单 / 歌单 / 歌手 / MV / 主视觉。
     分类 / 流 / 歌词 / 评论体积大（约 8.5MB）且变化少，仍随包内置，不白耗用户流量。
   ★ 每个文件独立成败：拿到几个算几个，只要核心两件（pool/charts）到位就刷新界面。 */
const DB_LIVE = ["pool","charts","library","artists","mv","hero"];
async function fetchLive(timeoutMs){
  const got = {};
  await Promise.all(DB_LIVE.map(async n=>{
    const gk = "__DWG_DB_" + n.toUpperCase();
    try{ window[gk] = null; }catch(e){}
    const ok = await loadScript(CDN_DYN + n + ".js", timeoutMs||9000);
    const v = window[gk];
    if(ok && v && typeof v === "object") got[n] = v;
  }));
  if(!got.pool || !got.charts) return null;   // 核心缺失 → 保持包内快照，绝不半截刷新
  return got;
}

/* =====================================================================
   全量曲库目录（10 万级 → 无上限）：manifest + 分片 + 分块搜索索引
   —— 内置快照只保证「首屏秒开 + 断网可用」，真正的海量曲库按需拉取

   为什么索引是「纯文本分块」而不是 JSON：
   30 万条 [[名,歌手,id,片],…] 解析出来的对象图约是文本体积的 10 倍，
   WebView 会被拖垮。改成「一行一条、\u0001 分隔」的字符串块后：
     · 内存 ≈ 文本体积（就是几个大字符串，没有几百万个小对象）；
     · 检索用 indexOf 在字符串上滑，命中才切那一行 —— 零额外分配。
   每块约 4 万行，后台并发 3 路渐进拉，边拉边可搜（搜到多少算多少）。
   ===================================================================== */
let CDNCAT = CDN + "catalog/";
let CDNJS  = CDNCAT + "js/";        // 云端也放一份同名脚本分块，供有网时热更新
/* ↑ 用 let 而非 const：探到时效锚点后要整体切到 @<sha>/data/（见 probeTide）。
   曲库清单/分块在 iOS 上是 <script> 注入（file:// 拦 fetch），所以换引用即生效。 */
const CSEP = "\u0001";
const SH_PACK = 10;                 // 每个 cat-sh-NN.js 里装 10 片（见 cloud/tools/mkcatalog_js.py）

/* 按需注入 <script src> 并等它执行完。
   为什么用 script 而不是 fetch（2026-10-05 定案）：
     · 实测中国网络直连 cdn.jsdelivr.net 只有 1~8 KB/s（走代理才 440 KB/s）——纯 CDN 方案不可用；
     · 所以曲库随包内置，而 file:// 下 WebView **拦 fetch/XHR、不拦 script/img 子资源**；
     · 用 script 一处代码同时吃「包内文件」与「CDN」两个来源，无需平台分支。 */
function loadScript(src, timeoutMs){
  /* ★ 节点回落（2026-10-06 三测定案，见上方 CDN_NODES 注释）：
       实测 gcore 会整节点被 RST —— 若只认这一个节点，**数据/索引/曲库全链路一起断**。
       这里把「同一个 path 依次在 gcore → fastly → cdn 上试」收口在这一处：
       内核里所有 CDN 加载（data/*.js、assets/*.js、catalog/cat-*.js、时效锚点）
       都经 loadScript，所以一处改动覆盖全部，不会漏。
       ★ 非 jsDelivr 的 URL（包内相对路径 / 上游图）变体只有它自己 → 行为与原来完全一致。 */
  const tries = cdnVariants(src);
  let ti = 0;
  return new Promise(resolve=>{
    const once = ()=>{
      const url = tries[ti];
      let done=false;
      const el=document.createElement("script");
      const fin=ok=>{
        if(done) return; done=true; clearTimeout(timer);
        if(!ok && ti < tries.length-1){ ti++; once(); return; }   // 换节点再试
        resolve(ok);
      };
      const timer=setTimeout(()=>fin(false), timeoutMs||30000);
      el.async=true; el.onload=()=>fin(true); el.onerror=()=>fin(false); el.src=url;
      (document.head||document.documentElement).appendChild(el);
    };
    once();
  });
}
/* ★ 并行赛马加载（2026-10-07 新增）：把同一 path 的**多个节点 URL 同时注入**，
   谁先回谁赢。**只给小文件用**（时效锚点 64B、内核清单这类）：
     · 同一个 path 在不同节点上内容**完全一致**，所以"抢答"没有任何语义副作用；
     · 大文件（数据 2.4MB / 图片）仍走 loadScript 串行 —— 并行会让三个节点同时回源，
       白烧三倍流量并可能触发限流，得不偿失。
   ★ 为什么单靠 loadScript 不够：锚点探测每次只给 3 秒，而节点质量会翻转
     （实测 fastly 冷取 18~47s）。串行时「前排节点慢」会把预算吃光，真正快的节点
     根本轮不到 → 锚点永远探不到 → 整套「秒级生效」静默失效。赛马把总耗时压成
     **最快那个节点的耗时**，与「谁快谁慢」无关。
   ★ 全失败才算失败：全部 onerror（或总超时）才 resolve(false)，绝不误判成功。 */
function loadScriptRace(src, timeoutMs){
  const tries = cdnVariants(src);
  if(tries.length <= 1) return loadScript(src, timeoutMs);   // 非 CDN（包内相对路径）无需赛马
  return new Promise(resolve=>{
    let done=false, pending=tries.length;
    const timer=setTimeout(()=>{ if(!done){ done=true; resolve(false); } }, timeoutMs||6000);
    tries.forEach(u=>{
      const el=document.createElement("script");
      el.async=true;
      el.onload =()=>{ if(!done){ done=true; clearTimeout(timer); resolve(true); } };
      el.onerror=()=>{ if(--pending<=0 && !done){ done=true; clearTimeout(timer); resolve(false); } };
      el.src=u;
      (document.head||document.documentElement).appendChild(el);
    });
  });
}
function absURL(rel){ try{ return new URL(rel, document.baseURI).href; }catch(e){ return rel; } }
/* 包内资源定位（内核热更新后必需）：
   内核被热更到沙盒后，document.baseURI 指向沙盒目录，而随包内置的曲库分块 cat-*.js
   仍然躺在 App 包内 —— 再用相对路径就会 404（曲库直接空掉）。
   原生壳启动时注入 window.__DWG_RES__ = 包内资源目录的绝对 file:// URL，
   这里优先用它；网页/Android 场景没有该变量，自动退回原行为（相对路径）。 */
function resURL(rel){
  const base = (typeof window.__DWG_RES__==="string" && window.__DWG_RES__) || "";
  if(base){ try{ return new URL(rel, base).href; }catch(e){} }
  return absURL(rel);
}

const CATALOG = {
  man:null, ready:false, loading:null, idxLoading:null, err:"",
  base:"", mode:"local",                     // base=="" → 读包内；否则读 CDN
  idxTxt:[], idxDone:0, idxTotal:0,
  shards:new Map(), busy:new Map(), _shPack:{},
  count(){ return this.man ? (this.man.count||0) : 0; },
  fmt(){ const c=this.count(); return c? (c>=10000? (c/10000).toFixed(1)+" 万" : String(c)) : "—"; },
  idxPct(){ return this.idxTotal ? Math.round(this.idxDone*100/this.idxTotal) : 0; },
  searchReady(){ return this.idxTxt.length>0; },
  async load(){
    if(this.ready) return true;
    if(this.loading) return this.loading;
    this.loading=(async()=>{
      // ① 包内清单（零网络、必然最快） ② 拿不到才退 CDN
      const keep=window.__CATMAN; window.__CATMAN=null;
      let ok=await loadScript(resURL("cat-manifest.js"), 2500);
      let m=window.__CATMAN;
      if(ok && m && m.count){ this.base=""; this.mode="local"; }
      else{
        window.__CATMAN=null;
        ok=await loadScript(CDNJS+"cat-manifest.js", 15000);
        m=window.__CATMAN; this.base=CDNCAT; this.mode= ok&&m&&m.count ? "cdn" : "local";
      }
      if(!m || !m.count){ window.__CATMAN=keep; this.err="曲库清单取不到"; this.loading=null; return false; }
      this.man=m;
      const ch=(m.idx&&m.idx.chunks)||[];
      this.idxTotal=ch.length; this.idxDone=0;
      this.ready=true; this.err="";
      document.dispatchEvent(new CustomEvent("dwg:catalog"));
      this.loadIdx();                          // 索引不阻塞目录就绪
      this.refresh();                          // 后台看云端有没有更新版（拿不到就静默放弃）
      return true;
    })();
    return this.loading;
  },
  /* 增量刷新：包内是随包版，云端流水线可能有更新的；只有 updated 真变了才切 */
  refresh(){
    if(this.mode!=="local") return;
    const cur=(this.man&&this.man.updated)||"";
    setTimeout(async ()=>{
      const keep=window.__CATMAN; window.__CATMAN=null;
      const ok=await loadScript(CDNJS+"cat-manifest.js", 15000);
      const m=window.__CATMAN;
      if(!ok || !m || !m.count || !m.updated || m.updated===cur){ window.__CATMAN=keep; return; }
      window.__CATMAN=m;
      this.man=m; this.base=CDNCAT; this.mode="cdn";
      const ch=(m.idx&&m.idx.chunks)||[];
      this.idxTxt=new Array(ch.length); this.idxDone=0; this.idxTotal=ch.length;
      this.shards=new Map(); this.busy=new Map(); this._shPack={};
      this.loadIdx();
      document.dispatchEvent(new CustomEvent("dwg:catalog"));
    }, 1500);
  },
  /* 索引分块渐进载入：3 路并发，每块到位就发事件让页面增量刷新结果 */
  loadIdx(){
    if(this.idxLoading) return this.idxLoading;
    const ch=(this.man&&this.man.idx&&this.man.idx.chunks)||[];
    if(!ch.length) return Promise.resolve(false);
    if(!this.idxTxt.length) this.idxTxt=new Array(ch.length);
    const base=this.base;
    this.idxLoading=(async()=>{
      let next=0;
      const worker=async()=>{
        while(next<ch.length){
          const i=next++;
          if(this.idxTxt[i]) continue;
          if(base===""){                             // 包内：脚本分块
            await loadScript(resURL("cat-"+ch[i].replace(/\.txt$/,".js")), 60000);
            this.idxTxt[i]=(window.__CATIDX&&window.__CATIDX[i])||"";
          }else{
            try{ const r=await fetch(base+ch[i]); this.idxTxt[i]= r.ok ? await r.text() : ""; }
            catch(e){ this.idxTxt[i]=""; }
          }
          this.idxDone++;
          document.dispatchEvent(new CustomEvent("dwg:catidx"));
        }
      };
      await Promise.all([worker(),worker(),worker()]);
      document.dispatchEvent(new CustomEvent("dwg:catidx"));
      return true;
    })();
    return this.idxLoading;
  },
  async shard(i){
    if(this.shards.has(i)) return this.shards.get(i);
    if(this.busy.has(i)) return this.busy.get(i);
    const f=((this.man&&this.man.shards)||[])[i]; if(!f) return null;
    const base=this.base;
    const p=(async()=>{
      if(base===""){                              // 包内：按 10 片一包取
        const g=Math.floor(i/SH_PACK);
        if(!this._shPack[g]) this._shPack[g]=loadScript(resURL("cat-sh-"+String(g).padStart(2,"0")+".js"), 60000);
        await this._shPack[g];
        const a=(window.__CATSH||{})[i];
        if(a) this.shards.set(i,a);
        this.busy.delete(i); return a||null;
      }
      const r=await fetch(base+f.file).catch(()=>null);
      const a=r&&r.ok? await r.json().catch(()=>null) : null;
      if(a) this.shards.set(i,a);
      this.busy.delete(i); return a;
    })();
    this.busy.set(i,p); return p;
  },
  /* 目录记录 → 内核统一的歌曲结构（带 .id 即可直接出流） */
  /* ★ 2026-10-07：cv/ov 必须透传 —— 否则曲库路径「原唱置顶」完全失效（srchRank 拿不到 cv，cv===2 的 +6 重罚永不触发）。
     两个来源都读：shard 记录自带 cv/ov；索引命中 h 也带 cv/ov（见调用点）。 */
  map(rec){ return {t:rec.n, s:rec.a, a:rec.b||"", cov:rec.p||"", dur:Math.round((rec.d||0)/1000), id:rec.i, cat:true, cv:+(rec.cv||0), ov:+(rec.ov||0), src:rec.src||""}; },
  /* 索引块里扫关键词：命中落在「歌名/歌手」两段内才算，避免撞上 id/片号造成假命中 */
  search(q, cap){
    const nq=norm(q); if(!nq || !this.idxTxt.length) return [];
    const out=[], seen=new Set(), lim=cap||100;
    for(let c=0;c<this.idxTxt.length && out.length<lim;c++){
      const txt=this.idxTxt[c]; if(!txt) continue;
      let from=0;
      while(out.length<lim){
        const p=txt.indexOf(nq, from);
        if(p<0) break;
        let ls=txt.lastIndexOf("\n", p); ls = ls<0 ? 0 : ls+1;
        let le=txt.indexOf("\n", p);     le = le<0 ? txt.length : le;
        from = le+1;
        let cut=0, k=0;                                   // cut = 第 3 个分隔符之后的位置
        while(k<3){ const s2=txt.indexOf(CSEP, cut); if(s2<0){ cut=txt.length; break; } cut=s2+1; k++; }
        if(p-ls>=cut) continue;                           // 命中在 id/片号/原名段 → 不是歌名/歌手命中
        const f=txt.slice(ls,le).split(CSEP);
        /* ★ 2026-10-07 多源 id 血案：`+f[2]` 对**超长 id** 会丢精度。
           咪咕 contentId 是 18 位（600930000002751847），远超 JS 的 MAX_SAFE_INTEGER
           （2^53-1 = 9007199254740991）→ `+` 一转就变成 …751900，请求错 id、静默无声。
           B 站 bvid 是字母串，`+` 直接 NaN → 被下面的 `if(!id)` 静默丢掉。
           判据：**≤15 位纯数字**才转 Number（网易 songId / 酷我 rid 都落在这一档，与老数据同型），
           其余一律当**不透明字符串**原样带走。写端 harvest._sid() 用同一把尺子，保证分片同型，
           否则 refs.set(s.id) 与 refs.get(rec.i) 一个字符串一个数字，封面永远补不上。
           cv: 1=原唱 / 2=翻唱 / 0=未知；ov: 翻唱指向的原唱 id（也可能是 18 位咪咕 id，同理处理）
           —— 主人要求「原唱就是原唱 翻唱就是翻唱」：搜索里原唱置顶，翻唱带角标仍可见。
           ★ trim 不是多余的：索引是**纯文本**，Windows 产物可能是 CRLF，
             而 src 正是**每行最后一个字段** → 会带上 "\r"，`sid==="migu"` 恒 false，
             多源歌静默退回网易直链。写端已显式 newline="\n"，这里再兜一层。 */
        const raw=String(f[2]==null?"":f[2]).trim();
        const id=(/^\d{1,15}$/.test(raw)) ? +raw : raw;
        if(!id || seen.has(id)) continue;
        seen.add(id);
        const rawOv=String(f[7]==null?"":f[7]).trim();
        const ov=(/^\d{1,15}$/.test(rawOv)) ? +rawOv : rawOv;
        const src=(f[8]||"").trim()||"wy";
        /* ★ 2026-10-07 第 9 段 src（多源）：索引行从 8 段升到 9 段，老行没有 f[8] → 缺省 "wy"。
           不解析它，多源曲目（migu/kw/bili）落库后端上仍按网易 id 拼直链 → 100% 拿不到音频。 */
        out.push({i:id, sh:+f[3], t:f[4]||f[0], s:f[5]||f[1], cv:+(f[6]||0), ov:ov, src:src});
      }
    }
    return out;
  },
  /* 搜索索引不含封面：按需把命中的分片拉回来，补封面/时长（最多 12 片） */
  async decorate(hits, refs){
    const need=[...new Set(hits.map(h=>h.sh))].slice(0,12);
    const blobs=await Promise.all(need.map(i=>this.shard(i)));
    blobs.forEach(b=>{ if(!b) return; b.forEach(rec=>{ const r=refs.get(rec.i); if(!r) return;
      if(rec.p && r.img && !r.img.dataset.done){ r.img.src=rec.p; r.img.dataset.done="1"; }
      if(rec.d && r.dur) r.dur.textContent=fmt(Math.round(rec.d/1000)); }); });
  }
};

/* 当前只有根页时才原地重建（避免打断二级页/播放器） */
function rebuildCurrentRoot(){
  if(Nav.stack.length!==1) return;
  const cur=Nav.stack[0]; if(!cur||!ROOTS[cur.id]) return;
  const h=ROOTS[cur.id]();
  cur.node.innerHTML=h.html; cur.onMount=h.onMount;
  if(h.onMount) h.onMount(cur.node);
  setTab(cur.id);
}

/* 重建当前栈顶页（根页或从「我的」推进来的二级页），刷新数据后原地刷新用 */
const PUSH_BUILDERS={ settings:()=>buildSettings(), library:()=>buildLibrary(), mv:()=>buildMV() };
function rebuildTop(){
  const top=Nav.stack[Nav.stack.length-1]; if(!top) return;
  const b = (ROOTS[top.id] ? ROOTS[top.id]() : (PUSH_BUILDERS[top.id] ? PUSH_BUILDERS[top.id]() : null));
  if(!b) return;
  top.node.innerHTML=b.html; top.onMount=b.onMount;
  if(b.onMount) b.onMount(top.node);
}

/* 后台静默刷新：拿到新数据才重绘（stale-while-revalidate） */
async function refreshLive(){
  if(window.__NO_LIVE__) return false;
  const out = await fetchLive(9000);
  if(!out) return false;
  applyBundle(out, true);
  rebuildCurrentRoot();
  return true;
}

/* 手动刷新（设置页按钮用） */
async function loadDB(){
  const out = await fetchLive(9000);
  if(out) applyBundle(out, true); else applyBundle(snapBundle(), false);
  rebuildCurrentRoot();
  return DB.live;
}

/* =====================================================================
   工具
   ===================================================================== */
const $ = s=>document.querySelector(s);
const el = (tag,cls,html)=>{const e=document.createElement(tag); if(cls)e.className=cls; if(html!=null)e.innerHTML=html; return e;};
const esc = s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const norm = s=>String(s||"").toLowerCase().replace(/[\s\-_（）()\[\]【】·,.，。'"!！?？~～&]/g,"");
/* 原唱/翻唱分离：**优先用云端下发的 cv 字段**（网易云 originCoverType 实测语义：
   1=原曲/原唱、2=翻唱），名字关键词只作兜底（快照老数据没有 cv）。
   cv 由 harvest 写入 shard / 索引第 7 段，见 cloud/tools/harvest.py original_gate。 */
const CV_RE=/(翻唱|翻自|cover|伴奏|伴唱|卡拉\s?ok|karaoke|instrumental|清唱|原唱[:：({（]|demo\s?版)/i;
function isCv(t,s,a,cv){
  if(cv===2) return true;                                // 云端明确标的翻唱
  if(cv===1) return false;                               // 云端明确标的原唱（关键词可能误伤）
  return CV_RE.test(String(t||"")+"\u0001"+String(s||"")+"\u0001"+String(a||""));
}
/* ★★ 2026-10-22 主人要求「伴奏和歌曲区分」—— 旧版把伴奏也算成「翻唱」，
   于是列表里一首伴奏挂着「翻唱」角标：既冤枉了翻唱，也让人误以为点进去是唱的。
   现在单独识别「非人声/演奏类」，给独立蓝紫角标「伴奏」，
   并把它排在更后面（伴奏/纯音乐在搜索里抢原曲位置是最典型的「张冠李戴」体感）。 */
const INST_RE=/(伴奏|伴唱|卡拉\s?ok|karaoke|instrumental|off\s?vocal|无人声|纯音[乐曲]|轻音乐|钢琴版|吉他版|古筝版|口琴版|演奏版|鼓谱|曲谱|和声版|升调|降调|消音)/i;
function isInst(t,s,a){
  return INST_RE.test(String(t||"")+"\u0001"+String(a||"")+"\u0001"+String(s||""));
}
/* ★★ 2026-10-22 「张冠李戴」第二道闸：视频投稿当歌曲。
   典型脏条目（真出现在旧歌库里）：「4K超清修复《海阔天空》1996现场版，目测全站最清晰！」
   歌手="邓仔中意Beyond"；「周杰伦《稻香》无损音质」歌手="音乐分享经典"。
   这类条目的「歌手」其实是 UP 主，「歌名」其实是标题 —— 搜正版歌名时它们会挤到前面。
   数据侧已修（build.py 不再把 bili 命中写进歌库），端上再补一道：**显著降权 + 原唱模式隐藏**。 */
const JUNK_RE=/(4K\s*修复|8K|hi-?res|无损音质|超清|高清修复|中文字幕|字幕版|完整版|合集|剪辑|解说|reaction|纯享|车载|dj版|加速版|慢速版|ktv|幕后|花絮|歌曲串烧)/i;
function isJunk(t,s,a){
  return JUNK_RE.test(String(t||"")+"\u0001"+String(s||"")+"\u0001"+String(a||""));
}
/* 列表去重：同一首（归一化歌名+歌手）只留第一条 —— 云端多源合并后仍可能有
   301 组重复键（75,997 首里 325 行），端上不再让它们重复出现。
   注意：**只在同一份列表内去重**，跨列表（比如「全部歌曲」与「收藏」）互不影响。 */
function dedupeSongs(list){
  const seen=new Set(), out=[];
  for(const s of (list||[])){
    const k=skey(s.t||s.title||"", s.s||s.singer||"");
    if(seen.has(k)) continue;
    seen.add(k); out.push(s);
  }
  return out;
}
/* 搜索相关度（越小越靠前）：歌手精确命中 > 歌手前缀 > 歌手含 > 歌名精确 > 歌名含 > 专辑含 > 其他；
   翻唱/伴奏版本在同档内再降权 —— 搜「伍佰」「走在冷风中」绝不能让翻唱压过本尊。
   ★ 2026-10-06 主人点名：「查走在冷风中原唱必须排第一，不能出现翻唱」，
     所以 cv=2 直接 +6 重罚（比关键词兜底 +2 更狠），确保原唱永远在翻唱前面。 */
function srchRank(s, nq){
  const st=norm(s.s), tt=norm(s.t), at=norm(s.a||"");
  let r = st===nq?0 : st.startsWith(nq)?1 : st.includes(nq)?2
        : tt===nq?3 : tt.includes(nq)?4
        : at.includes(nq)?6 : 7;
  /* 伴奏/纯音乐最靠后：它们同档时最容易「顶掉原曲」（用户点开发现没人声） */
  if(isInst(s.t,s.s,s.a)) return r+9;
  /* 视频投稿/剪辑标题：比伴奏更该靠后（它连歌都不是） */
  if(isJunk(s.t,s.s,s.a)) return r+12;
  if(s.cv===2) return r+6;                               // 云端标的翻唱：重罚
  return r + (CV_RE.test(String(s.t||"")+"\u0001"+String(s.s||"")+"\u0001"+String(s.a||""))?2:0);
}
/* 真播放索引：与云端 build._skey() 逐字符对齐（归一化后 40 / 30 截断）
   ★★ 截断必须按**码点**，不能按 UTF-16 码元：
      JS 的 String.prototype.slice() 数的是 UTF-16 code unit，
      emoji / 非 BMP 汉字（如 𠮷、🕯）占 2 个 —— 一旦标题里出现，
      切出来的长度就比 Python 的 s[:40]（按码点）短，键直接对不上，
      表现为「这首歌的封面/播放映射莫名其妙查不到」。
      Array.from() 走迭代器 = 按码点拆，与 Python 语义严格一致。
      实测当前曲库 101256 首里命中 0 首（潜伏 bug），但契约必须严密。 */
const cpslice=(s,n)=>{ s=String(s==null?"":s); return Array.from(s).slice(0,n).join(""); };
function skey(t,s){ return cpslice(norm(t),40)+"|"+cpslice(norm(s),30); }
/* 全量曲库的歌自带网易云 id → 直出流；内置快照的歌走预解析映射 */
/* =====================================================================
   多源取流（★ 2026-10-06 主人「VIP也想办法能到」的落地）
   网易云对 VIP/付费歌只给 HTML 下载页 → 原唱整片消失。云端已按
   wy → kw(酷我) → mg(咪咕) → bili 回退选好**长效 id**，这里按 src 拼直链。
   ★ 值只存 id（直链带签名会过期），src 决定怎么拼。
   ===================================================================== */
function stRec(s){                                     // 取该曲的 streams 记录
  if(!s) return null;
  if(s.id){
    const r=DB.st[skey(s.t,s.s)]; if(r) return r;
    /* ★ 2026-10-07 多源：曲库记录自带的 src 优先于「默认网易」。
       曲库 31k+ 首里已混入 migu/kw/bili 源（见 harvest cmd_multi），
       它们的 id 不是网易 songId，硬拼 outer/url 必然 404 → 必须按 src 走对应直链。 */
    const sid=String(s.src||"wy").trim()||"wy";
    if(sid!=="wy"){ const o={src:sid}; o[sid]=s.id; return o; }
    return {src:"wy", wy:s.id};
  }
  return DB.st[skey(s.t,s.s)]||null;
}
function streamOf(s){ const r=stRec(s); return r? (r[r.src||"wy"]) : null; }
function stInfo(s){ return stRec(s); }
function streamId(s){                                  // 当前生效平台的 id
  const r=stRec(s); if(!r) return null; return r[r.src||"wy"]||r.wy||null;
}
function srcUrl(s){
  const r=stRec(s); if(!r) return "";
  const sid=String(r.src||"wy").trim()||"wy", id=r[sid];
  return srcUrlOf(sid, id);
}
/* 按「源 + id」拼直链（srcUrl 与候选链共用一套口径，避免两处规则漂移） */
function srcUrlOf(sid, id){
  sid=String(sid||"wy").trim()||"wy";
  if(!id) return "";
  if(sid==="kw") return "http://antiserver.kuwo.cn/anti.s?type=convert_url&rid=MUSIC_"+id+"&format=mp3&response=url";
  if(sid==="migu"||sid==="mg") return "https://app.pd.nf.migu.cn/MIGUM3.0/v1.0/content/sub/listenV2?contentId="+id+"&resourceType=2&format=mp3";
  return "https://music.163.com/song/media/outer/url?id="+id+".mp3";
}

/* =====================================================================
   多源映射（xmap）+ 播放故障自动换源（2026-10-22 新增）
   ---------------------------------------------------------------------
   为什么加：体检曲库 75,997 首时发现 **多源同曲映射 = 0 条** ——
   某首歌的网易直链一 404 就彻底没声，所谓「备用线路」根本不存在。
   现在云端用酷我/咪咕搜索把「同一个人在别的平台唱同一首歌」的 id 落成
   data/streams/xmap.js（严格校验：标题剥后缀后必须完全相等 + 歌手归一相等/包含
   + 时长差 ≤3s + 排除伴奏/现场/DJ/翻唱），端上按这个表组候选链。
   换源时机：<audio> 触发 error（而不是盲跳下一首）→ 先换线路，全挂才跳歌。
   ===================================================================== */
const XMAP=(function(){
  const KEY="dwg.xmap.v1";
  let map=null, p=null;
  function load(){
    if(p) return p;
    try{ const c=localStorage.getItem(KEY); if(c){ const o=JSON.parse(c);
      if(o&&typeof o==="object") map=o; } }catch(e){}
    p=loadScript(((typeof CDN_DYN!=="undefined"&&CDN_DYN)?CDN_DYN:CDN)+"streams/xmap.js", 12000)
      .then(ok=>{
        if(ok&&window.__DWG_XMAP&&typeof window.__DWG_XMAP==="object"){
          map=window.__DWG_XMAP;
          try{ localStorage.setItem(KEY, JSON.stringify(map)); }catch(e){}
        }
        return map;
      }).catch(()=>map);
    return p;
  }
  return {
    boot(){ load(); },
    ids(s){ if(!map||!s) return null; return map[skey(s.t,s.s)]||null; },
    size(){ return map?Object.keys(map).length:0; }
  };
})();

/* 候选链顺序按「实测可用率」排：网易云 > 咪咕 > 酷我
   （2026-10-22 实测：咪咕匿名可播率最高、搜索也最准；酷我华语主流曲常年缺版权，
     搜「稻香 周杰伦」20 条里只有 DJ版/片段/搞笑版，原版根本不在了）。 */
const SRC_ORDER=["wy","migu","kw"];
function streamCands(s){
  const out=[], seen=new Set();
  const push=(src,id)=>{
    if(!id) return;
    const u=srcUrlOf(src,id);
    if(!u||seen.has(u)) return;
    seen.add(u); out.push({src:src, id:String(id), url:u});
  };
  const m=XMAP.ids(s);
  if(m&&m.ids){
    const own=m.src||"wy";
    push(own, m.ids[own]);
    SRC_ORDER.forEach(k=>{ if(k!==own) push(k, m.ids[k]); });
  }
  const r=stRec(s);
  if(r){ const sid=String(r.src||"wy"); push(sid, r[sid]||r.wy); }
  else if(s&&s.id) push(s.src||"wy", s.id);
  return out;
}
function cmtOf(s){ return (s&&DB.cmt[skey(s.t,s.s)])||null; }
/* 歌词：先看包内快照，没有则等实时拉取（undefined=还没取过，null=取过但没有）
   2026-10-06 修「词不同步不对版」：取流用网易云 id，取词却按「歌名|歌手」查快照，
   两把尺子量同一首歌 → 翻唱版/VIP 歌拿到的是别人版本的词，时间轴天然对不上。
   现在统一成「id 优先、名字兜底」：与 streamOf() 同源，取到哪一版的音频就用哪一版的词。 */
function lyrKey(s){ const id=streamId(s); return id?("i:"+id):("n:"+skey(s.t,s.s)); }
function lyricOf(s){ const k=lyrKey(s);
  if(LYRLIVE.cache && (k in LYRLIVE.cache)) return LYRLIVE.cache[k];
  const nk="n:"+skey(s.t,s.s);
  if(LYRLIVE.cache && (nk in LYRLIVE.cache)) return LYRLIVE.cache[nk];
  const hit=DB.lyr&&DB.lyr[k]; if(hit) return hit;
  const hn=DB.lyr&&DB.lyr[nk]; if(hn) return hn;
  /* 兼容老格式（纯名字键）——线上已有 1290 首按此存 */
  const old=DB.lyr&&DB.lyr[skey(s.t,s.s)]; if(old) return old;
  /* ③ LRCLIB 分片（云端已对齐好时间轴）。排在快照之后：中文歌网易云官方词更准，
     LRCLIB 补的是「快照里没有 / 没有时间轴」的那一大片。分片没加载完时返回 null，
     由 LYRLIVE.fetch 去异步取，渲染层先显示"正在取歌词"。 */
  const lr=LRJS.peek(skey(s.t,s.s));
  if(lr&&lr.l) return {l:lr.l, t:"", src:"lrclib"};
  return undefined; }
/* 兜底直链：见上方 srcUrl()（按 src 拼 wy/kw/mg 各自直链）
   —— 桥挂了也不会没声。 */

/* =====================================================================
   原生能力桥（可选增强 · 缺失时全部走内置回落，绝不影响播放）
   为什么需要它：网易云高码率接口 / 歌词接口都不返回 CORS 头，
   file:// 页面里 fetch 会被浏览器拦死；交给原生壳代发就没有这问题。
   协议：JS → {id, method, params}；原生 → window.__dwgCb(id, base64(json))
   ===================================================================== */
const Native = {
  _seq:0, _cb:{},
  ios(){ return !!(window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.dwg); },
  and(){ return !!(window.dwgNative && typeof window.dwgNative.call === "function"); },
  get ok(){ return PLAT!=="web" && (this.ios()||this.and()); },
  call(method, params, timeoutMs){
    return new Promise(resolve=>{
      if(!this.ok){ resolve(null); return; }
      const id=++this._seq; let done=false;
      const fin=v=>{ if(done) return; done=true; delete this._cb[id]; resolve(v); };
      this._cb[id]=fin;
      setTimeout(()=>fin(null), timeoutMs||8000);
      const payload={id:id, method:method, params:params||{}};
      try{
        if(this.ios()) window.webkit.messageHandlers.dwg.postMessage(payload);
        else window.dwgNative.call(JSON.stringify(payload));
      }catch(e){ fin(null); }
    });
  }
};
window.__dwgCb = function(id, b64){
  const f = Native._cb[id]; if(!f) return;
  let v=null;
  try{
    const bin=atob(b64); const u8=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) u8[i]=bin.charCodeAt(i);
    v=JSON.parse(new TextDecoder().decode(u8));
  }catch(e){ v=null; }
  f(v);
};

/* =====================================================================
   内核热更新（免推机）：启动后静默问云端有没有新内核
   ---------------------------------------------------------------------
   为什么整个下载交给原生：file:// 页面的 fetch 跨源被 WebView 拦死，
     页面既读不到 CDN 的 kernel.json，也拉不动 6MB 的 app.html。
   流程：本页只发一条 kcheck{base} → 原生取清单、比版本、下载、校验、落盘。
   生效时机：**下次冷启动**（不在本次会话里重载，避免打断正在听的歌）。
   失败静默：任何异常都只是「这次没更成」，绝不打扰用户、绝不影响播放。
   为什么用 gcore 节点：实测国内 cdn.jsdelivr.net 拉大文件会回源
     raw.githubusercontent.com（被墙，25s 只下到 176KB），而 gcore 节点 855KB/s。
   ===================================================================== */
const KUP = {
  /* 云端内核目录：内核源码仓库（ios-music-app）的 kernel/ 目录。
     ★★★ 2026-10-06 二次实测修正：@latest 方案作废，改回 @main。
       判决性实测（真值取 api.github.com，零缓存；同一时刻并发对比）：
         真值               version=0a4a3eb50f03   ← 最新
         @latest            version=38fbc94aaf49   ← 旧（别名解析被顽固缓存，purge 打不动）
         @main              version=4963b79d8e55   ← 更旧
         @v1.0.21           version=0a4a3eb50f03   ← 立即生效 ✅
         @main?t=<时间戳>    version=4963b79d8e55   ← query 不能绕缓存
         @latest?t=<时间戳>  version=38fbc94aaf49   ← query 不能绕缓存
       结论：jsDelivr 对「分支/别名」的缓存，purge 与 query 都击不穿；
             只有**从未见过的具体引用**（新 semver tag / commit sha）才立即回源。
             → @latest 既没兑现「分钟级」，缓存时长还从分支的 12 小时变成别名的 7 天，
               **比 @main 更差**，且依赖仓库里存在 release（解析不出会挂起）。
              故回退 @main —— 它是分支，12 小时自然过期，是**确定性**上限，永不断供。
     ★★ 2026-10-06 终局结论（推翻上一版的「webhook 假设」）：
        曾以为「用 SSH 真凭据推 → 触发 jsDelivr push webhook → 秒级生效」。
        反证实验：cloud 仓改用 deploy key 推，`data/probe.json`（**全新文件名**）
        7 秒即取到 ✅，但同一次提交里的 `data/assets/cv.json`（**老 URL**）纹丝不动
        → 「真凭据触发 webhook」不成立。真相只有一个：**jsDelivr 按 URL 缓存，
        新 URL 才秒回，老 URL（@main / @latest）一律吃硬缓存**。
        → 所以靠「换凭据」救不了内核热更，必须**换引用**：先用时效锚点探到
          `kernel/win/<窗口>.js` 里的 sha，再用 `@<sha>/kernel/` 问原生要内核。
          （deploy key 仍保留：它让 checkout 能用 SSH，且成本为零，无害。）
     ★ 节点不再是「一个」，而是池子（2026-10-06 三测：gcore 会整节点被 RST，
       fastly 同时刻 200 —— 见上方 CDN_NODES 注释）。base / fallbackBase 只是池子的
       前两档；check() 里还会对锚点 sha 生成「每档节点各一个 base」，一起轮询。
       全部拿不到 → 原生 kcheck 返回 ok=false，端上继续用包内内核，不影响启动
       （原则：宁可慢，不能断）。 */
  /* ★★★ 2026-10-23：内核分发目录必须按平台分开（安卓热更一直失效的第二个真因）。
     远端 kernel/dist.js 是 iOS 的 pack.py 打的壳，里面硬写了 data-shell="ios"
     和内嵌的 window.__PLATFORM__="ios"。
     安卓要是下这一份装进沙盒，下次冷启动就以为自己是 iOS → PLAT!=="android" →
     电视 D-pad 版式、原生桥分支、返回栈全部走错，等于把 App 弄坏。
     所以安卓用独立的 kernel/android/，清单也各管各的，互不污染。
     （sub() 在 PLAT 确定后才取值 —— PLAT 来自 __PLATFORM__，脚本顶部已定，安全。） */
  sub(){ return PLAT==="android" ? "android/" : ""; },
  get base(){ return CDN_NODES[0] + CDN_REPO + "ios-music-app@main/kernel/" + this.sub(); },
  get fallbackBase(){ return CDN_NODES[1] + CDN_REPO + "ios-music-app@main/kernel/" + this.sub(); },
  KEY:"dwg.kup.last",          // 上次检查时间，避免每次启动都查
  /* ★★★ 2026-10-23 从 6 小时改成 30 分钟（用户实测「推了新版手机上看不到」的第三个真因）。
     原来 6 小时才查一次：重装 APK 后首启记账 → 当天推新内核 → 冷启动发现「距上次 6 小时内」
     → 直接 return，一次都不问 CDN → 用户体感就是「远程更新根本没实现」。
     代价其实极小：一次检查 = 3 个节点并行探锚点脚本（命中 ~2s）+ 一条 192 字节 kernel.json；
     版本相同就不再下 8MB 内核。启动后延后 8 秒且串在首屏之后，不抢资源。 */
  everyMs: 30*60*1000,         // 30 分钟最多查一次
  check(force, done){
    if(PLAT==="web" || !Native.ok){ if(done) done({ok:false,msg:"当前环境不支持热更新"}); return; }
    try{
      const last=+(localStorage.getItem(this.KEY)||0);
      if(!force && Date.now()-last < this.everyMs) return;
    }catch(e){}
    // 延后 8 秒：绝不和首屏渲染、曲库预取抢资源
    setTimeout(()=>{
      console.log("[DWG] KUP 开始检查（"+(force?"手动":"自动")+"）");
      const pull=b=>Native.call("kcheck", {base:b}, 120000);
      /* ★★★ 先探内核仓的时效锚点（kernel/win/<窗口>.js）：
           @main 的 kernel.json 受分支 12 小时硬缓存 —— 刚推的内核手机上要等半天；
           锚点文件 URL 天生是新的 → 秒级；拿到 sha 后把 base 换成 @<sha>/kernel/，
           同样是全新 URL → 原生 kcheck 立刻就能比出版本差、下到新内核。
           探不到（无网/窗口文件缺失）→ 原样用 @main，只是慢，**永不断供**。 */
      probeTideKernelFresh(5000, 14000).catch(()=>{ if(done) done({ok:false,msg:"检查失败（网络不通）"}); return null; }).then(sha=>{
        const bases = [];
        // 锚点 sha 的 base：每一档节点各来一个（节点级冗余，不押注单一节点）
        const sub = this.sub();   // "" （iOS）/ "android/" —— 见 base 上方注释
        if(sha) CDN_NODES.forEach(n=>bases.push(n + CDN_REPO + "ios-music-app@" + sha + "/kernel/" + sub));
        bases.push(this.base, this.fallbackBase);
        for(let i=2;i<CDN_NODES.length;i++) bases.push(CDN_NODES[i] + CDN_REPO + "ios-music-app@main/kernel/" + sub);
        // 依次问；谁先给出新内核就用谁（拿到的 r 已是 updated 就不再往下问，不浪费流量）
        return bases.reduce((p,b)=>p.then(r=>(r && r.ok && r.updated) ? r : pull(b)),
                            Promise.resolve(null));
      }).then(r=>{
        /* 只在“真的问到了 CDN”才记时间戳：通网顺畅时 6 小时一次，
           但断网/节点全挂时不记账 —— 下次启动立刻重试，而不是静默 6 小时。 */
        if(r && r.ok){ try{ localStorage.setItem(this.KEY, String(Date.now())); }catch(e){} }
        if(r && r.ok && r.updated){
          // 已落盘，下次启动生效。此处只留一条控制台痕迹，不做任何 UI 打扰。
          console.log("[DWG] 内核已更新到 "+r.version+"（"+Math.round((r.bytes||0)/1048576*10)/10+"MB），下次启动生效");
        }
        if(!r || !r.ok) console.log("[DWG] 内核检查未成功："+(r&&r.msg||"无响应"));
        else if(!r.updated) console.log("[DWG] 内核已是最新："+r.version);
        if(done) done(r||{ok:false,msg:"没有可用的更新源"});
      }).catch(()=>{ if(done) done({ok:false,msg:"检查失败"}); });
      /* 判据说明（沿用旧逻辑的结论，仍适用）：
         回落判据必须是 r.updated，**不能**是 r.ok —— 节点之间回源时间不同步
         （A 节点可能还在发旧清单），此时原生比对 version 与本地相同 →
         返回 ok=true / updated=false。若只看 r.ok 就停，会把「节点发旧清单」
         误判成「已是最新」而放弃换源，等于白白错过本来能拿到的内核。
         成本只是多拉一次 192 字节的 kernel.json，版本相同就不会下 6MB 内核，可忽略。 */
    }, force?300:8000);
  }
};

/* ---- 音质档位（匿名实测：standard 128k / higher 192k / exhigh 320k）---- */
const QUAL_KEY="dwg.qual.v1";
const QUALS=[
  {k:"ex",   n:"超高", sub:"320kbps · 推荐"},
  {k:"high", n:"高品", sub:"192kbps"},
  {k:"std",  n:"标准", sub:"128kbps · 最省流量"}
];
const QUAL_LV={ex:"exhigh", high:"higher", std:"standard"};
const Qual={ v:(localStorage.getItem(QUAL_KEY)||"ex"),
  set(k){ this.v=k; try{ localStorage.setItem(QUAL_KEY,k); }catch(e){} },
  name(){ const q=QUALS.find(x=>x.k===this.v); return q?q.n:"超高"; } };

/* ---- 音源解析器：优先高码率（20 分钟有效，缓存 10 分钟）
   ★ 2026-10-06：**只对网易云(src=wy)生效**。原生桥的 stream 接口走的是网易云高码率，
     酷我/咪咕的曲目没有对应通道 → 直接走 srcUrl() 兜底，别白等 8 秒超时。 ---- */
const SR={ cache:{},
  key(s){ const r0=stRec(s); if(!r0 || (r0.src||"wy")!=="wy") return "";
    const id=r0.wy; return id? (id+"@"+QUAL_LV[Qual.v]) : ""; },
  fresh(s){ const k=this.key(s); if(!k) return null; const c=this.cache[k];
    return (c && Date.now()-c.at < 10*60*1000) ? c : null; },
  async get(s){
    const r0=stRec(s); if(!r0 || (r0.src||"wy")!=="wy") return null;
    const id=r0.wy; if(!id) return null;
    const lv=QUAL_LV[Qual.v], key=id+"@"+lv;
    const c=this.cache[key];
    if(c && Date.now()-c.at < 10*60*1000) return c;
    if(!Native.ok) return null;
    if(!this._inflight) this._inflight={};
    if(!this._inflight[key]) this._inflight[key]=Native.call("stream",{id:id, level:lv}, 8000)
      .then(r=>{ this._inflight[key]=null; return r; }, ()=>{ this._inflight[key]=null; return null; });
    const r=await this._inflight[key];
    if(r && r.url){ r.at=Date.now(); this.cache[key]=r; return r; }
    return null;
  },
  warm(s){ if(!Native.ok || Qual.v==="std") return; if(this.fresh(s)) return; this.get(s).catch(()=>{}); },
  lvTier(){ return Qual.v; }
};

/* ---- 「我的」：本地真持久化（收藏 / 最近播放 / 下载）---- */
const Store = {
  k:"dwg.music.v2",
  d:{fav:[],recent:[],dl:[]},
  load(){ try{ this.d=Object.assign({fav:[],recent:[],dl:[]}, JSON.parse(localStorage.getItem(this.k)||"{}")); }catch(e){} return this.d; },
  save(){ try{ localStorage.setItem(this.k, JSON.stringify(this.d)); }catch(e){} },
  pack(s){ return {k:skey(s.t,s.s), t:s.t, s:s.s, a:s.a||"", cov:s.cov||"", dur:s.dur||0, at:Date.now()}; },
  revive(x){ return {t:x.t, s:x.s, a:x.a||"", cov:x.cov||"", dur:x.dur||0}; },
  favOn(s){ return this.d.fav.some(x=>x.k===skey(s.t,s.s)); },
  toggleFav(s){ const k=skey(s.t,s.s); const i=this.d.fav.findIndex(x=>x.k===k);
    if(i>=0){ this.d.fav.splice(i,1); this.save(); return false; }
    this.d.fav.unshift(this.pack(s)); this.save(); return true; },
  pushRecent(s){ const k=skey(s.t,s.s); this.d.recent=[this.pack(s)].concat(this.d.recent.filter(x=>x.k!==k)).slice(0,200); this.save(); },
  isDl(s){ return this.d.dl.some(x=>x.k===skey(s.t,s.s)); },
  addDl(s){ const k=skey(s.t,s.s); if(this.d.dl.some(x=>x.k===k)) return false;
    this.d.dl.unshift(this.pack(s)); this.save(); return true; },
  delDl(k){ this.d.dl=this.d.dl.filter(x=>x.k!==k); this.save(); },
  songs(kind){ return (this.d[kind]||[]).map(x=>this.revive(x)); },
  count(kind){ return (this.d[kind]||[]).length; },
  clear(kind){ this.d[kind]=[]; this.save(); }
};
Store.load();

/* =====================================================================
   自建歌单（对标 QQ音乐/网易云的「我的歌单」）
   —— 存在本机 localStorage，免登录、断网也在；键独立于 Store，互不污染。
   ===================================================================== */
const PL = (function(){
  const K="dwg.pl.v1";
  let list=[];
  function load(){
    try{ const x=JSON.parse(localStorage.getItem(K)||"[]"); list=Array.isArray(x)?x:[]; }catch(e){ list=[]; }
    list=list.filter(p=>p&&p.id&&p.name&&Array.isArray(p.songs));
    return list;
  }
  function save(){ try{ localStorage.setItem(K, JSON.stringify(list)); }catch(e){} }
  load();
  return {
    all(){ return list; },
    count(){ return list.length; },
    get(id){ return list.find(p=>p.id===id)||null; },
    create(name){
      name=String(name||"").replace(/\s+/g," ").trim().slice(0,30);
      if(!name) return null;
      if(list.some(p=>p.name===name)) return null;
      const p={id:"pl"+Date.now().toString(36)+Math.random().toString(36).slice(2,5),
               name:name, at:Date.now(), songs:[]};
      list.unshift(p); save(); return p;
    },
    del(id){ list=list.filter(p=>p.id!==id); save(); },
    /* 收录：按 skey 去重（同曲不同源算同一首） */
    has(id, s){ const p=this.get(id); return !!(p && p.songs.some(x=>x.k===skey(s.t,s.s))); },
    add(id, s){
      const p=this.get(id); if(!p) return false;
      const k=skey(s.t,s.s);
      if(p.songs.some(x=>x.k===k)) return false;
      p.songs.unshift(Store.pack(s)); save(); return true;
    },
    remove(id, k){ const p=this.get(id); if(!p) return; p.songs=p.songs.filter(x=>x.k!==k); save(); },
    songs(id){ const p=this.get(id); return p?p.songs.map(x=>Store.revive(x)):[]; }
  };
})();

const fmt = t=>{t=Math.max(0,Math.floor(t||0));return Math.floor(t/60)+":"+String(t%60).padStart(2,"0");};
/* =====================================================================
   私人 FM（对标 QQ音乐/网易云的私人 FM）：口味加权抽歌 + 放到底自动续，
   永不停止；刚听过的 20 首直接避开，不会连着放同一批。
   ===================================================================== */
const FM = (function(){
  function taste(){
    const like={};
    (Store.d.fav||[]).forEach(x=>{ if(x.s) like[x.s]=(like[x.s]||0)+4; });
    (Store.d.recent||[]).forEach(x=>{ if(x.s) like[x.s]=(like[x.s]||0)+1; });
    return like;
  }
  function pick(n, exclude){
    const ex=new Set(exclude||[]);
    const like=taste();
    const pool=(DB.songs||[]).filter(s=>s&&s.t&&s.s
      && !ex.has(skey(s.t,s.s)) && !isCv(s.t,s.s,s.a,s.cv) && !isInst(s.t,s.s,s.a));
    const scored=pool.map(s=>({s:s, w:(like[s.s]||0)+Math.random()*10}));
    scored.sort((a,b)=>b.w-a.w);
    const out=[], byS={};
    for(const it of scored){
      if(out.length>=n) break;
      const c=byS[it.s.s]||0; if(c>=2) continue;   // 同歌手最多 2 首
      byS[it.s.s]=c+1; out.push(it.s);
    }
    return out;
  }
  return {
    pick:pick,
    start(n){
      const list=pick(n||60,(Store.d.recent||[]).slice(0,20).map(x=>x.k));
      if(!list.length){ toast("曲库还没载入完，稍等一下"); return false; }
      P.load(list,0,"私人FM"); openPlayer(); return true;
    },
    /* 队列放到底时补货 */
    more(n,q){ return pick(n||40,(q||[]).slice(-40).map(s=>skey(s.t,s.s))); }
  };
})();

/* =====================================================================
   每日推荐（对标 QQ音乐「每日 30 首」/ 网易云「每日推荐」）
   —— 真效果：按本机收藏+最近播放的歌手做口味加权，日期做随机种子，
      同一天反复进来**同一批歌**（不乱跳），第二天自动换一批。
      取的都是曲库里能真播的原唱（翻唱/伴奏不进推荐）。
   ===================================================================== */
const Daily = (function(){
  const K="dwg.daily.v1";
  function day(){ const d=new Date(); const p=n=>String(n).padStart(2,"0");
    return d.getFullYear()+"-"+p(d.getMonth()+1)+"-"+p(d.getDate()); }
  function hash(s){ let h=2166136261; for(const c of String(s)){ h^=c.charCodeAt(0); h=Math.imul(h,16777619); } return h>>>0; }
  function rng(a){ return function(){ a=(a+0x6D2B79F5)|0;
    let t=Math.imul(a^(a>>>15), 1|a); t=(t+Math.imul(t^(t>>>7), 61|t))^t;
    return ((t^(t>>>14))>>>0)/4294967296; }; }
  function list(){
    const today=day();
    let st=null;
    try{ st=JSON.parse(localStorage.getItem(K)||"null"); }catch(e){}
    if(st && st.day===today && Array.isArray(st.songs) && st.songs.length){
      return st.songs.map(x=>Store.revive(x)).filter(s=>s&&s.t);
    }
    const like={};
    (Store.d.fav||[]).forEach(x=>{ if(x.s) like[x.s]=(like[x.s]||0)+3; });
    (Store.d.recent||[]).forEach(x=>{ if(x.s) like[x.s]=(like[x.s]||0)+1; });
    const pool=(DB.songs||[]).filter(s=>s&&s.t&&s.s
      && !isCv(s.t,s.s,s.a,s.cv) && !isInst(s.t,s.s,s.a));
    const r=rng(hash(today));
    const scored=pool.map(s=>({s:s, w:(like[s.s]||0)*2.2 + r()*10}));
    scored.sort((a,b)=>b.w-a.w);
    const out=[], byS={};
    for(const it of scored){
      if(out.length>=40) break;
      const c=byS[it.s.s]||0; if(c>=3) continue;   // 同一歌手最多 3 首，别整成「单曲循环」
      byS[it.s.s]=c+1; out.push(it.s);
    }
    try{ localStorage.setItem(K, JSON.stringify({day:today, songs:out.map(s=>Store.pack(s))})); }catch(e){}
    return out;
  }
  return { list:list, day:day, count(){ return this.list().length; } };
})();
/* 数据新鲜度展示：ISO → "10-22 22:36"（榜单页/曲库页用它自证「不是假数据」） */
const fmtUpd = s=>{
  if(!s) return "—";
  const d=new Date(s);
  if(isNaN(d.getTime())) return String(s).slice(5,16).replace("T"," ");
  const p=n=>String(n).padStart(2,"0");
  return `${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
};
const durs = s=>{ // "4:30" / "845:22" -> 秒
  const p=String(s||"").split(":").map(Number);
  if(p.length===3)return p[0]*3600+p[1]*60+p[2];
  if(p.length===2)return p[0]*60+p[1];
  return 0;};
const plays = n=>{n=+n||0; return n>=1e8?(n/1e8).toFixed(1)+"亿":n>=1e4?(n/1e4).toFixed(1)+"万":String(n);};
function ph(text,seed){ // 无封面时的确定性渐变占位
  const h=Math.abs([...(text||"?")].reduce((a,c)=>a*31+c.charCodeAt(0),7))%360;
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="120" height="120"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="hsl(${h} 46% 34%)"/><stop offset="1" stop-color="hsl(${(h+52)%360} 40% 18%)"/></linearGradient></defs><rect width="120" height="120" fill="url(#g)"/><text x="60" y="72" font-size="44" fill="rgba(255,255,255,.5)" text-anchor="middle" font-family="-apple-system,sans-serif" font-weight="700">${esc((text||"♪").slice(0,1))}</text></svg>`;
  return "data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg);
}
function toast(msg,icon){
  const t=$("#toast");
  t.innerHTML=(icon||"")+`<span>${esc(msg)}</span>`;
  t.dataset.in="1"; clearTimeout(t._h); t._h=setTimeout(()=>t.dataset.in="0",1900);
}
