/* =====================================================================
   电视 / 遥控器模式（D-pad 空间导航）
   ---------------------------------------------------------------------
   ★★★ 2026-10-22：主人要「安卓能上大屏电视」。光有横屏不够 —— 遥控器只有
     方向 + 确定 + 返回，而网页里 .row/.gcard 这些 div 默认**不可聚焦**，
     电视上等于按什么都没反应（以前的真实状态）。
   这里做三件事，全部自包含、手机端零影响（只有真电视/显式 ?tv=1 才启用）：
     ① 给可交互元素补 tabIndex，确定键 = click；
     ② 方向键按**几何最近**找下一个焦点（不是 DOM 顺序）—— 网格/横滑轨都能顺着走；
     ③ 焦点永远 scrollIntoView，且焦点环在 CSS 里给了高对比描边。
   判据：原生壳注入 window.__DWG_TV__=1（Android 侧按 leanback/television 特性判定）；
     调试：URL 带 ?tv=1。UA 里含 TV/Android TV 也认。
   ===================================================================== */
const TVMODE = { on:false };
const TV_SEL = ".row,.gcard,.mcard,.acard,.moodcard,.kw,.btn,.ibtn,.tab,.gi,.sitem,.qchip,.tab2";
function tvIs(){
  if(window.__DWG_TV__===1) return true;
  if(/[?&]tv=1/.test(location.search)) return true;
  return /(Android TV|GoogleTV|\bTV\b|BRAVIA|MiBOX|Leanback)/i.test(navigator.userAgent||"");
}
function tvCands(){
  const out=[];
  document.querySelectorAll(TV_SEL).forEach(n=>{
    const r=n.getBoundingClientRect();
    if(r.width<8||r.height<8) return;
    const st=getComputedStyle(n);
    if(st.visibility==="hidden"||st.display==="none"||+st.opacity<0.15) return;
    if(r.bottom<0||r.top>innerHeight) return;         // 屏幕外的先不比，滚到了会进来
    /* 未打开的播放器/MV 层、收起的标签栏里的元素一律不算焦点候选
       （#mvplayer 未打开时没有 data-in 属性，不能只比 =""） */
    const pl=n.closest(".player");
    if(pl && pl.getAttribute("data-in")!=="1") return;
    if(n.closest(".tabbar.hide")||n.closest(".sheet:not([data-in='1'])")) return;
    if(!n.hasAttribute("tabindex")) n.setAttribute("tabindex","0");
    out.push(n);
  });
  return out;
}
function tvMove(dir){
  const list=tvCands(); if(!list.length) return false;
  let cur=document.activeElement;
  if(!cur || cur===document.body || !list.includes(cur)){
    /* 还没有焦点：先给「当前页第一个」—— 但优先给屏幕最上方的那个 */
    list.sort((a,b)=>a.getBoundingClientRect().top-b.getBoundingClientRect().top);
    list[0].focus(); return true;
  }
  const a=cur.getBoundingClientRect(), ax=a.left+a.width/2, ay=a.top+a.height/2;
  let best=null, bd=Infinity;
  for(const n of list){
    if(n===cur) continue;
    const b=n.getBoundingClientRect(), bx=b.left+b.width/2, by=b.top+b.height/2;
    const dx=bx-ax, dy=by-ay;
    let ok=false, pri=0, sec=0;
    if(dir==="down"){ ok=dy>6;  pri=dy;  sec=Math.abs(dx); }
    if(dir==="up"){   ok=dy<-6; pri=-dy; sec=Math.abs(dx); }
    if(dir==="right"){ok=dx>6;  pri=dx;  sec=Math.abs(dy); }
    if(dir==="left"){ ok=dx<-6; pri=-dx; sec=Math.abs(dy); }
    if(!ok) continue;
    const d=pri+sec*2.6;                 // 同轴优先，斜着的不抢
    if(d<bd){ bd=d; best=n; }
  }
  if(best){
    best.focus();
    try{ best.scrollIntoView({block:"center",inline:"nearest",behavior:"smooth"}); }catch(e){}
    return true;
  }
  return false;
}
function tvClick(){
  const a=document.activeElement;
  if(a && a!==document.body && typeof a.click==="function"){ a.click(); return true; }
  return false;
}
function tvKey(e){
  const k=e.key;
  const map={ArrowDown:"down",ArrowUp:"up",ArrowLeft:"left",ArrowRight:"right"};
  if(map[k]){
    /* 播放器进度条获得焦点时，左右键交给它微调（不抢） */
    if(document.activeElement && document.activeElement.classList.contains("track")) return;
    if(tvMove(map[k])){ e.preventDefault(); e.stopPropagation(); }
    return;
  }
  if(k==="Enter"||k===" "||k==="Select"||k==="NumpadEnter"){
    if(tvClick()){ e.preventDefault(); e.stopPropagation(); }
  }
}
function tvBoot(){
  if(!tvIs()) return;
  TVMODE.on=true;
  document.documentElement.setAttribute("data-tv","1");
  document.addEventListener("keydown", tvKey, true);
  /* 首次落焦：等首屏渲染完，把焦点放到第一个榜单行/入口，遥控器一按就有反应 */
  setTimeout(()=>{ if(!document.activeElement || document.activeElement===document.body) tvMove("down"); }, 1800);
  console.log("[DWG] 电视模式已启用（D-pad 空间导航）");
}

/* =====================================================================
   导航管理：每个打开的层都有明确的"关/返回"
   ===================================================================== */
const Nav = {
  stack: [],        // 页面栈 [{id,render}]
  overlays: [],     // 覆盖层 [{id,close}]
  base: null,
  lock: false
};
function pageEl(id){
  let n = document.querySelector(`.page[data-id="${id}"]`);
  return n;
}
function pushPage(id, builder){
  if(Nav.lock) return;
  const cur = Nav.stack[Nav.stack.length-1];
  let node = pageEl(id);
  if(node){ node.remove(); }
  node = el("div","page"); node.dataset.id=id;
  node.innerHTML = builder.html;
  node.style.transform="translateX(100%)";
  $("#stack").appendChild(node);
  Nav.stack.push({id, node, onMount: builder.onMount});
  // 老页面下移
  if(cur){ cur.node.dataset.under="1"; cur.node.dataset.base=""; }
  requestAnimationFrame(()=>{ node.dataset.in="1"; node.style.transform=""; });
  if(builder.onMount) builder.onMount(node);
  history.pushState({p:id},"","#"+id);
}
function popPage(){
  if(Nav.stack.length<=1){ return false; }
  const top = Nav.stack.pop();
  top.node.dataset.in="0"; top.node.style.transform="translateX(100%)";
  setTimeout(()=>top.node.remove(),360);
  const prev = Nav.stack[Nav.stack.length-1];
  if(prev){ prev.node.dataset.under=""; prev.node.dataset.base="1"; prev.node.dataset.in="1"; prev.node.style.transform=""; }
  return true;
}
function back(){
  // 优先关覆盖层，再退页面栈（这就是"能返回"的核心规则）
  if(Nav.overlays.length){ Nav.overlays[Nav.overlays.length-1].close(); return true; }
  if(Nav.stack.length>1){ popPage(); return true; }
  return false;
}
// 原生壳（iOS / Android）调用：返回键交给网页处理；返回 true=已消费，false=可退出 App
function __plOpen__(){ const p=$("#player"); return !!(p && p.dataset.in==="1"); }
function __tabId__(){ const t=document.querySelector(".tab.on"); return t?t.dataset.tab:"home"; }
window.__appBack__ = function(){
  if(Nav.overlays.length){ Nav.overlays[Nav.overlays.length-1].close(); return true; }
  if(Nav.stack.length>1){ popPage(); return true; }
  if(__plOpen__()){ closePlayer(); return true; }
  if(__tabId__()!=="home"){ gotoTab("home"); return true; }
  return false;
};
// 原生壳调用：查询是否还能返回（用于同步系统返回手势）
window.__canBack__ = function(){
  return Nav.overlays.length>0 || Nav.stack.length>1 || __plOpen__() || __tabId__()!=="home";
};
// 原生壳注入平台标识后重绘（getPlatform 见 PLAT）
window.__setPlatform__ = function(p){ PLAT = p || "web"; };
// 壳模式诊断探针：图片加载失败 / JS 报错 → console（原生壳把 console 转发到 logcat）
if(document.documentElement.dataset.shell){
  document.addEventListener("error",function(e){
    var t=e.target;
    if(t && t.tagName==="IMG") console.log("DWG-IMGFAIL "+(t.currentSrc||t.src||"(empty)"));
  },true);
  window.addEventListener("error",function(e){ console.log("DWG-JSERR "+e.message); });
}
function openOverlay(id, node, onClose){
  Nav.overlays.push({id, close:()=>{ 
    node.dataset.in=""; 
    setTimeout(()=>{ if(Nav.overlays.every(o=>o.id!==id)) node.remove(); },380);
    Nav.overlays = Nav.overlays.filter(o=>o.id!==id);
    if(onClose) onClose();
  }});
  return Nav.overlays[Nav.overlays.length-1];
}
function page(html){ return {html, onMount:null}; }
function navBar(title, rightHtml, noBack){
  return `<div class="nav">
    ${noBack?'<span class="spacer"></span>':`<button class="ibtn" data-back aria-label="返回">${ICONS.back}</button>`}
    <h1>${esc(title)}</h1>
    <div class="nav-right">${rightHtml||'<span class="spacer"></span>'}</div>
  </div>`;
}

/* =====================================================================
   底部标签栏
   ===================================================================== */
const TABS=[
  {id:"home", label:"首页", icon:'<svg width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M3 10.5L12 3l9 7.5"/><path d="M5.5 9.6V20h13V9.6"/></svg>'},
  {id:"charts", label:"榜单", icon:'<svg width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg>'},
  {id:"mine", label:"我的", icon:'<svg width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="3.8"/><path d="M4.4 20c.7-3.9 4-5.9 7.6-5.9s6.9 2 7.6 5.9"/></svg>'}
];
function buildTabs(){
  const tb=$("#tabbar"); tb.innerHTML="";
  TABS.forEach(t=>{
    /* ★ 2026-10-22：图标包一层 .tic —— 选中态靠这层的胶囊底把「这是按钮」说清楚
       （旧版只换颜色，玻璃底上根本看不出选中） */
    const b=el("div","tab"+(Nav.stack[0]&&Nav.stack[0].id===t.id?" on":""),
      `<div class="tic">${t.icon}</div><span>${t.label}</span>`);
    b.dataset.tab=t.id;
    b.tabIndex=0;                          /* 电视遥控器/AirMouse 可聚焦 */
    b.onclick=()=>gotoTab(t.id);
    b.onkeydown=e=>{ if(e.key==="Enter"||e.key===" "){ e.preventDefault(); gotoTab(t.id); } };
    tb.appendChild(b);
  });
}
function setTab(id){ [...document.querySelectorAll(".tab")].forEach(t=>t.classList.toggle("on",t.dataset.tab===id)); }
function gotoTab(id){
  // 先规范化：关掉所有覆盖层
  while(Nav.overlays.length) Nav.overlays[Nav.overlays.length-1].close();
  // 把页面栈退回到根
  while(Nav.stack.length>1) popPage();
  const root=Nav.stack[0];
  if(root && root.id===id){ setTab(id); root.node.scrollTop=0; return; }
  if(root) root.node.remove();
  Nav.stack=[];
  const def=ROOTS[id]();
  const node=el("div","page"); node.dataset.id=id; node.dataset.base="1"; node.dataset.in="1";
  node.innerHTML=def.html; $("#stack").insertBefore(node,$("#stack").firstChild);
  Nav.stack.push({id,node,onMount:def.onMount});
  if(def.onMount) def.onMount(node);
  setTab(id);
  history.replaceState({p:id},"","#"+id);
}

/* =====================================================================
   播放引擎（真播放：<audio> 驱动 · 直链来自云端实测可播映射，非模拟）
   ===================================================================== */
const Cur = { mv:null, mvPlaying:false };

/* 播放模式：一个按钮循环切换四态，状态真实生效 */
const MODES = [{k:"order",n:"顺序播放"},{k:"list",n:"列表循环"},{k:"one",n:"单曲循环"},{k:"shuffle",n:"随机播放"}];
const MI = {
  order:'<svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 7h11M4 12h11M4 17h11"/><path d="M19 6v12M19 18l-2.4-2.6M19 18l2.4-2.6"/></svg>',
  list:'<svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 2l4 4-4 4"/><path d="M3 11V9a4 4 0 0 1 4-4h14"/><path d="M7 22l-4-4 4-4"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/></svg>',
  one:'<svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 2l4 4-4 4"/><path d="M3 11V9a4 4 0 0 1 4-4h14"/><path d="M7 22l-4-4 4-4"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/><path d="M11.4 10.6v4M11.4 10.6l-1.3 1"/></svg>',
  shuffle:'<svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 3h5v5M4 20L21 3M21 16v5h-5M15 15l6 6M4 4l5 5"/></svg>'
};
/* 音量交给系统：app 内不设任何音量乘数、不改播放速率，
   这样手机实体音量键调的就是真实出声大小（应用内音量条会和实体键打架，已下线）。 */

/* =====================================================================
   播放增强：倍速 / 睡眠定时（对标 QQ音乐·网易云的「倍速」「定时关闭」）
   —— 纯 audio 元素能力，不依赖原生桥，Android/iOS/桌面浏览器同一套行为。
   ===================================================================== */
const ICO_CLOCK='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="8.4"/><path d="M12 7.6V12l3.2 1.9"/></svg>';
const ICO_SPEED='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 17a8.6 8.6 0 1 1 16 0"/><path d="M12 13.6l4.2-4.6"/><circle cx="12" cy="17" r="1.5" fill="currentColor" stroke="none"/></svg>';

const Rate = (function(){
  const K="dwg.rate.v1", OPTS=[0.5,0.75,1,1.25,1.5,1.75,2];
  let v=1;
  try{ const x=parseFloat(localStorage.getItem(K)); if(x>=0.25&&x<=3) v=x; }catch(e){}
  function label(x){ return (x===1?"1.0":String(x))+"×"; }
  function apply(){
    const a=document.getElementById("au");
    if(a){
      try{
        a.playbackRate=v;
        // 变速不变调：三大前缀都写一遍，老 WebView 也认
        a.preservesPitch=true; a.webkitPreservesPitch=true; a.mozPreservesPitch=true;
      }catch(e){}
    }
    const b=document.getElementById("plRate");
    if(b){ b.textContent=label(v); b.classList.toggle("hi", v!==1); }
    const sb=document.getElementById("setRate");
    if(sb) sb.textContent=label(v);
  }
  return {
    v:()=>v, label:label, opts:()=>OPTS.slice(),
    set(x){
      v=Math.max(0.25, Math.min(3, +x||1));
      try{ localStorage.setItem(K, String(v)); }catch(e){}
      apply();
      toast(v===1?"已恢复原速":"播放速度 "+label(v));
    },
    apply
  };
})();

const Sleep = (function(){
  let endAt=0, tEnd=null, tTick=null, afterCur=false;
  function paint(){
    const b=document.getElementById("plSleep"); if(!b) return;
    if(!endAt){ b.textContent="定时"; b.classList.remove("on","hi"); return; }
    const left=Math.max(0, endAt-Date.now());
    b.textContent="定时 "+fmt(Math.ceil(left/1000));
    b.classList.add("on");
  }
  function clear(silent){
    if(tEnd){ clearTimeout(tEnd); tEnd=null; }
    if(tTick){ clearInterval(tTick); tTick=null; }
    endAt=0; afterCur=false; paint();
    if(!silent) toast("已关闭定时");
  }
  function fadeStop(){
    const a=document.getElementById("au");
    if(!a){ clear(true); return; }
    let vol=1;
    const iv=setInterval(()=>{
      vol-=0.09;
      if(vol<=0.02){
        clearInterval(iv);
        try{ a.pause(); }catch(e){}
        try{ a.volume=1; }catch(e){}
        clear(true);
        toast("定时结束，已暂停播放");
        P.paint();
        return;
      }
      try{ a.volume=Math.max(0.02,vol); }catch(e){}
    }, 380);
  }
  function arm(min){
    clear(true);
    if(!min) return;
    endAt=Date.now()+min*60000;
    tEnd=setTimeout(fadeStop, min*60000);
    tTick=setInterval(paint, 1000);
    paint();
    toast("已设置 "+min+" 分钟后停止");
  }
  return {
    set:arm,
    clear:()=>clear(false),
    active:()=>!!(endAt||afterCur),
    left:()=>endAt?Math.max(0,endAt-Date.now()):0,
    after(){ clear(true); afterCur=true; paint(); toast("播完当前这首就停"); },
    afterOn:()=>afterCur,
    /* 被 <audio> 的 ended 调用：返回 true 表示已接管（不要自动下一首） */
    consumeAfter(){
      if(!afterCur) return false;
      afterCur=false; paint();
      try{ P.au().pause(); }catch(e){}
      toast("定时结束，已停在当前曲");
      return true;
    },
    fadeStop
  };
})();

/* 倍速选择面板 */
function rateSheet(){
  openSheet("播放速度", "变速不变调 · 设置会被记住", Rate.opts().map(r=>({
    i:ICO_SPEED, l:r===1?"1.0× （正常）":r+"×", on:Rate.v()===r,
    fn:()=>Rate.set(r)
  })).concat([null, {i:ICONS.x, l:"恢复默认", fn:()=>Rate.set(1)}]));
}
/* 定时关闭面板 */
function sleepSheet(){
  const items=[
    {i:ICO_CLOCK, l:"15 分钟后", fn:()=>Sleep.set(15)},
    {i:ICO_CLOCK, l:"30 分钟后", fn:()=>Sleep.set(30)},
    {i:ICO_CLOCK, l:"60 分钟后", fn:()=>Sleep.set(60)},
    {i:ICO_CLOCK, l:"90 分钟后", fn:()=>Sleep.set(90)},
    null,
    {i:ICONS.pause, l:"播完当前这首就停", on:Sleep.afterOn(), fn:()=>Sleep.after()}
  ];
  if(Sleep.active()) items.push(null, {i:ICONS.x, l:"关闭定时", danger:true, fn:()=>Sleep.clear()});
  openSheet("定时关闭", Sleep.active()?("剩余 "+fmt(Math.ceil(Sleep.left()/1000))):"到点自动淡出暂停", items);
}

const P = { queue:[], i:0, playing:false, t:0, tot:0, ctx:"歌库", mode:"list", errs:0,
  _tok:0, qLabel:"",
  au(){ return document.getElementById("au"); },
  cur(){ return this.queue[this.i]||null; },
  load(list, idx, ctx){
    /* 队列去重：同一首（归一化歌名|歌手）只留一次 —— 榜单/歌单经常重复收录，连播不重歌 */
    const seen=new Set(), out=[];
    (list||[]).forEach(s=>{ const k=skey(s.t,s.s); if(seen.has(k)) return; seen.add(k); out.push(s); });
    this.queue=out;
    let ni=0;
    if(list && list[idx]){ const k=skey(list[idx].t,list[idx].s);
      const p=out.findIndex(s=>skey(s.t,s.s)===k); if(p>=0) ni=p; }
    this.i=ni; this.ctx=ctx||"歌库"; this.errs=0; this.start(true);
  },
  /* awaitQual=true 时（用户主动点播）等一小会儿拿高码率；自动续播不等待，绝不卡顿 */
  start(awaitQual){
    const s=this.cur(); if(!s) return;
    const a=this.au(), token=++this._tok;
    /* 候选链：本曲所有能播的线路（主源 + xmap 里的备用源）。出错时挨个换，换完才跳歌。 */
    this._cands=streamCands(s); this._ci=0;
    const fb=(this._cands[0]&&this._cands[0].url)||srcUrl(s);
    this.t=0; this.tot=s.dur||0; this.qLabel="";
    applyTheme(s);                       // 背景/主题跟随当前播放的封面主色
    Store.pushRecent(s);                 // 最近播放真落地（刷新不丢）
    $("#mini").classList.remove("hide");
    if(!fb){
      toast("「"+s.t+"」暂无可用音源","!");
      this.playing=false; this.paint(); this.errs++;
      if(this.errs<4) setTimeout(()=>this.next(1),700);
      return;
    }
    this._begin(s, token, fb, awaitQual);
  },
  async _begin(s, token, fb, awaitQual){
    const a=this.au();
    let u=fb, label="标准 128k";
    if(Native.ok && Qual.v!=="std"){
      const hit=SR.fresh(s);
      let r=hit;
      if(!r && awaitQual) r=await SR.get(s);
      if(token!==this._tok) return;                       // 期间已切歌 → 本结果作废
      if(r && r.url){ u=r.url; label=r.br>=320000?"超高 320k":r.br>=192000?"高品 192k":"标准 128k"; }
      if(!r && !hit) SR.warm(s);                          // 没等到就后台继续解析，下次即秒开
    }
    if(token!==this._tok) return;
    this.qLabel=label;
    this.playing=true;
    try{ a.volume=1; a.src=u; }catch(e){}
    Rate.apply();                                       // 换曲后重新落倍速（部分内核会重置）
    const pr=a.play(); if(pr&&pr.catch) pr.catch(()=>{});
    this.paint();
    this.warmNext();
  },
  warmNext(){
    const n=this.queue[this.i+1]; if(!n) return;
    const r=stRec(n); if(!r || (r.src||"wy")!=="wy") return;   // 非网易云不用桥预热
    if(!Native.ok || Qual.v==="std") return;
    if(SR.fresh(n)) return;
    SR.warm(n);
  },
  toggle(){ const a=this.au(); if(!this.cur()) return;
    if(a.paused){ const pr=a.play(); if(pr&&pr.catch) pr.catch(()=>{}); } else a.pause(); },
  /* 换源：当前线路播不了就试下一条。返回 true 表示已接管（别跳歌）。 */
  tryNextSrc(){
    const c=this._cands||[];
    if(this._ci+1>=c.length) return false;
    this._ci++;
    const n=c[this._ci];
    if(!n||!n.url) return false;
    const label = n.src==="wy"?"网易云线路" : n.src==="migu"?"咪咕线路" : n.src==="kw"?"酷我线路" : "备用线路";
    this.qLabel=label;
    try{
      const a=this.au(); a.src=n.url;
      const pr=a.play(); if(pr&&pr.catch) pr.catch(()=>{});
    }catch(e){ return false; }
    toast("这条线路不通，已切到"+label);
    this.paint();
    return true;
  },
  /* 插播「下一首」：真把这首塞到当前曲后面（不是只弹个 toast 骗人）。
     队列本来就按 skey 去重过，所以这里只需「若在后面则提上来」。 */
  nextUp(s){
    if(!s) return;
    const q=this.queue, cur=q[this.i];
    if(!cur){ this.load([s],0,"手动添加"); toast("已开始播放："+s.t); return; }
    const k=skey(s.t,s.s);
    if(k===skey(cur.t,cur.s)){ toast("这首正在播放"); return; }
    if(q[this.i+1] && skey(q[this.i+1].t,q[this.i+1].s)===k){ toast("已经是下一首了"); return; }
    const at=q.findIndex((x,idx)=>idx>this.i && skey(x.t,x.s)===k);
    if(at>this.i) q.splice(at,1);                 // 已在队列后面 → 抽出来提前
    q.splice(this.i+1,0,s);
    toast("已加入下一首："+s.t);
    const ns=document.getElementById("nextUpT");
    if(ns) ns.textContent=s.t;
  },
  next(d){
    const q=this.queue; if(!q.length) return;
    if(this.mode==="shuffle"&&q.length>1){ let n=this.i; while(n===this.i) n=Math.floor(Math.random()*q.length); this.i=n; }
    else{
      let n=this.i+(d==null?1:d);
      if(n>=q.length){
        /* 私人FM：放到底不回头，直接补一批新的接着放 */
        if(this.ctx==="私人FM" && (d==null||d>0)){
          const more=FM.more(40,q);
          if(more.length){ const at=q.length; q.push.apply(q,more); this.i=at; this.start(false); return; }
        }
        if(this.mode==="order"){ this.stop(); toast("已播放到最后一首"); return; }
        n=0;
      }
      if(n<0) n=q.length-1;
      this.i=n;
    }
    this.start(false);      // 自动续播不等待解析：下一首通常已预取好，直接秒开高码率
  },
  prev(){ const a=this.au();
    if(this.t>3){ try{ a.currentTime=0; }catch(e){} this.t=0; this.paint(); syncLyric(0); return; }
    this.next(-1); },
  stop(){ this.playing=false; const a=this.au();
    try{ a.pause(); a.removeAttribute("src"); a.load(); }catch(e){}
    this.paint(); },
  seek(f){ const a=this.au();
    if(a&&a.duration&&isFinite(a.duration)){ try{ a.currentTime=Math.max(0,Math.min(1,f))*a.duration; }catch(e){} }
    this.paint(); },
  cycleMode(){ const i=MODES.findIndex(m=>m.k===this.mode);
    this.mode=MODES[(i+1)%MODES.length].k;
    const b=document.getElementById("plMode");
    if(b){ b.innerHTML=MI[this.mode]; b.classList.toggle("on", this.mode!=="order"); }
    toast(MODES.find(x=>x.k===this.mode).n);
    return this.mode;
  },
  paint(){
    const s=this.cur(); if(!s) return;
    const cov=songCover(s,ph(s.t)), info=stInfo(s);
    $("#miniCov").src=cov; $("#miniT").textContent=s.t;
    const mS=$("#miniS"); mS.textContent=s.s+(s.a?" · "+s.a:""); mS._lt=mS.textContent;
    $("#plCov").src=cov; $("#plT").innerHTML=esc(s.t)+(isCv(s.t,s.s,s.a,s.cv)?'<span class="tag-cv">翻唱</span>':""); $("#plS").textContent=s.s+(s.a?" · "+s.a:"");
    $("#plFromLabel").textContent="正在播放"; $("#plFromSub").textContent=this.ctx;
    const qb=$("#plQual");
    if(qb){ const lab=this.qLabel||"标准 128k";
      qb.innerHTML='音质 · '+esc(lab)+' <span class="qarr">›</span>';
      qb.classList.toggle("hi", lab.indexOf("超高")===0); }
    const f=this.tot?Math.min(1,this.t/this.tot):0;
    $("#miniBar").style.width=(f*100)+"%";
    $("#plFg").style.width=(f*100)+"%"; $("#plKnob").style.left=(f*100)+"%";
    $("#plCur").textContent=fmt(this.t); $("#plTot").textContent=fmt(this.tot);
    this._lastCur=fmt(this.t); this._lastTot=fmt(this.tot);
    this.syncIcon();
    // 收藏 / 下载 状态回填
    const on=Store.favOn(s);
    const f1=$("#plFavBtn"), f2=$("#plActFav"), d1=$("#plActDl");
    if(f1) f1.classList.toggle("on", on);
    if(f2) f2.classList.toggle("on", on);
    if(d1) d1.classList.toggle("on", Store.isDl(s));
    if(document.getElementById("plLyric")) renderLyricIfNeeded(s);
  },
  /* 播放/暂停图标：只在状态真的变了（或节点被重建过）时才替换。
     旧版每次 timeupdate 都无条件 outerHTML 整体换掉两个 SVG —— 等于一秒销毁重建 8 次 DOM。 */
  syncIcon(){
    const has=$("#plPI")&&$("#miniPI");
    if(this._pi===this.playing && has) return;
    this._pi=this.playing;
    const pi=this.playing?ICONS.pause:ICONS.play;
    const a=$("#plPI"), b=$("#miniPI");
    if(a) a.outerHTML=pi.replace("<svg","<svg id=\"plPI\"");
    if(b) b.outerHTML=pi.replace("<svg","<svg id=\"miniPI\"");
  },
  /* ★ 发热治理③：进度心跳（timeupdate）专用轻量路径。
     旧版每次 timeupdate 直接调 paint() —— 全量重绘（标题/歌手/音质/收藏态/歌词重排 + 两次 outerHTML），
     一秒跑 4~8 次，还夹着 O(n) 的歌词扫描。现在只动「真的会变的三个数」：
     两根进度条 + 两个时间文案；歌词按 220ms 节流；图标按状态去重；
     并用 requestAnimationFrame 把同一帧内的多次事件合并成一次。 */
  tickProgress(){
    const a=this.au(); if(!a) return;
    this.t=a.currentTime||0;
    if(a.duration&&isFinite(a.duration)) this.tot=a.duration;
    const f=this.tot?Math.min(1,this.t/this.tot):0, pc=(f*100)+"%";
    const mb=document.getElementById("miniBar"); if(mb) mb.style.width=pc;
    const pf=document.getElementById("plFg"); if(pf) pf.style.width=pc;
    const pk=document.getElementById("plKnob"); if(pk) pk.style.left=pc;
    const c=fmt(this.t), cs=document.getElementById("plCur");
    if(cs&&this._lastCur!==c){ this._lastCur=c; cs.textContent=c; }
    const tt=fmt(this.tot), ts=document.getElementById("plTot");
    if(ts&&this._lastTot!==tt){ this._lastTot=tt; ts.textContent=tt; }
    this.syncIcon();
    MS.position();
    const now=(window.performance&&performance.now)?performance.now():Date.now();
    if(now-(this._lyrAt||0)>=220){ this._lyrAt=now; syncLyric(this.t); }
  },
};

/* <audio> 事件 → 真进度 / 真结束 / 真错误兜底 */
(function(){
  const a=document.getElementById("au"); if(!a) return;
  // ★ 发热治理③：timeupdate 走「合并到一帧一次 + 轻量路径」。
  //   同一帧内多次事件只处理一次；页面不可见时 rAF 不触发 → 后台播放零渲染开销。
  let tickQ=false;
  a.addEventListener("timeupdate",()=>{
    if(tickQ) return; tickQ=true;
    requestAnimationFrame(()=>{ tickQ=false; P.tickProgress(); });
  });
  a.addEventListener("loadedmetadata",()=>{ if(a.duration&&isFinite(a.duration)) P.tot=a.duration; P.paint(); });
  a.addEventListener("play",()=>{ P.playing=true; P.paint(); MS.playback("playing"); });
  a.addEventListener("pause",()=>{ P.playing=false; P.paint(); MS.playback("paused"); });
  a.addEventListener("ended",()=>{ if(Sleep.consumeAfter()) return; if(P.mode==="one"){ try{ a.currentTime=0; a.play(); }catch(e){} return; } P.next(1); });
  /* ★ 2026-10-22：出错先换源，不是直接跳歌。
     旧逻辑一响 error 就 toast「已跳过」→ 用户眼看着歌被跳掉，其实换个线路就能放。
     现在 streamCands() 给出了本曲的全部线路，挨个试完才认输。 */
  a.addEventListener("error",()=>{
    if(!P.cur()) return;
    if(P.tryNextSrc()) return;                 // 还有备用线路 → 已切过去，别动队列
    P.playing=false; P.errs++; P.paint();
    if(P.errs<4){ toast("本曲所有线路都不可用，已跳过","!"); setTimeout(()=>P.next(1),500); }
    else { toast("连续多首无可用音源"); }
  });
})();

/* =====================================================================
   锁屏 / 系统播放控制（MediaSession）：锁屏封面、标题、上下曲、拖进度
   ===================================================================== */
const MS = (function(){
  if(!("mediaSession" in navigator)) return {sync(){},playback(){},position(){}};
  const ms=navigator.mediaSession;
  const act=(n,f)=>{ try{ ms.setActionHandler(n,f); }catch(e){} };
  act("play",()=>{ const pr=P.au().play(); if(pr&&pr.catch) pr.catch(()=>{}); });
  act("pause",()=>P.au().pause());
  act("previoustrack",()=>P.prev());
  act("nexttrack",()=>P.next(1));
  act("seekbackward",d=>{ try{ P.au().currentTime=Math.max(0,P.au().currentTime-(d&&d.seekOffset||10)); }catch(e){} });
  act("seekforward",d=>{ try{ P.au().currentTime=Math.min(P.au().duration||1e9,P.au().currentTime+(d&&d.seekOffset||10)); }catch(e){} });
  act("seekto",d=>{ if(d&&d.seekTime!=null){ try{ P.au().currentTime=d.seekTime; }catch(e){} } });
  act("stop",()=>P.stop());
  return {
    sync(){                                   // 换歌时更新锁屏卡片
      const s=P.cur(); if(!s) return;
      try{
        ms.metadata=new MediaMetadata({title:s.t,artist:s.s,album:s.a||"大伟歌",
          artwork:[{src:songCover(s,ph(s.t)),sizes:"512x512",type:"image/webp"}]});
      }catch(e){}
      this.playback(P.au().paused?"paused":"playing");
    },
    playback(st){ try{ ms.playbackState=st; }catch(e){} },
    position(){                               // 锁屏进度条
      const a=P.au();
      if(a.duration&&isFinite(a.duration)&&!a.paused){
        try{ ms.setPositionState({duration:a.duration,position:a.currentTime||0,playbackRate:a.playbackRate||1}); }catch(e){}
      }
    }
  };
})();
/* 换歌同步锁屏：P.paint 在 start/事件里都会走，这里按曲 key 去重 */
let _msKey="";
(function(){
  const paint=P.paint.bind(P);
  P.paint=function(){ paint(); const s=this.cur(); const k=s?skey(s.t,s.s):"";
    if(k&&k!==_msKey){ _msKey=k; MS.sync(); } };
})();

/* =====================================================================
   歌词引擎（真 LRC：云端抓取落库 → 逐句滚动 + 与播放真同步）
   ===================================================================== */
/* 实时歌词拉取：包内快照没有的歌，用原生桥按需取（缓存一次，永不重复请求） */
const LYRLIVE={ cache:{}, tried:{} };
/* 纯 HTTP 兜底取词（无原生桥时用；歌词接口 CORS 开放，Web 也能直取）
   走两次：lv=1 原文 + tv=-1 翻译，与原生桥 DwgNet.swift 口径一致 */
LYRLIVE.http = async function(sid){
  try{
    const u="https://music.163.com/api/song/lyric?id="+sid+"&lv=1&kv=1&tv=-1";
    const j=await (await fetch(u,{mode:"cors"})).json();
    const l=(j&&j.lrc&&j.lrc.lyric)||"", t=(j&&j.tlyric&&j.tlyric.lyric)||"";
    if(!l && !t) return null;
    return {l:l, t:t, src:"wy-http"};
  }catch(e){ return null; }
};
LYRLIVE.fetch = async function(s){
  const k=lyrKey(s);                     /* id 优先：与取流同源，保证「这版音频配这版词」 */
  if(this.tried[k]) return;
  this.tried[k]=1;                       /* 先占位，避免连点换歌时重复请求 */
  const nk="n:"+skey(s.t,s.s);

  /* ① LRCLIB 分片（2026-10-22 新增）：云端 Actions 预取好的带时间轴歌词。
     ★ 这一条对**酷我/咪咕/QQ 曲目**是唯一有希望的来源 —— 它们没有词接口，
       旧版只能读包内快照（2400 首），覆盖不到就永远「暂无歌词」。 */
  try{
    const lr=await LRJS.get(skey(s.t,s.s));
    if(lr&&lr.l){
      const rec={l:lr.l, t:"", src:"lrclib"};
      this.cache[k]=rec; if(nk!==k) this.cache[nk]=rec;
      const cur=P.cur();
      if(cur&&lyrKey(cur)===k){ LY.key=""; renderLyricIfNeeded(cur); }
      return;
    }
  }catch(e){}

  /* ② 网易云 id 直取（中文歌官方词，还带翻译） */
  const r0=stRec(s);
  const wyId=(r0 && (r0.src||"wy")==="wy") ? r0.wy : (s&&s.id?s.id:null);
  /* 非网易云曲目：没有词接口 → 直接回落包内快照，别再空等 */
  if(!wyId){ this.cache[k]=DB.lyr&&DB.lyr[nk]||null; return; }
  /* 桥可用走桥（更稳）；桥不可用（Web 预览/桥未就绪）退回纯 HTTP —— 歌词接口 CORS 开放 */
  let r=null;
  if(Native.ok){ r=await Native.call("lyric",{id:wyId}, 8000).catch(()=>null); }
  if(!r || !r.l){ r=await LYRLIVE.http(wyId); }
  /* 双写：id 键（新，精确）+ 名字键（兼容包内快照的旧键） */
  const rec = (r && r.l) ? {l:r.l, t:r.t||"", src:"live"} : null;
  this.cache[k]=rec;
  if(nk!==k) this.cache[nk]=rec;
  const cur=P.cur();
  if(cur && lyrKey(cur)===lyrKey(s)){ LY.key=""; renderLyricIfNeeded(cur); }
};

/* =====================================================================
   LRCLIB 歌词分片（2026-10-22 新增）
   ---------------------------------------------------------------------
   为什么要有这一层（实测数据说话，别再走回头路）：
     · 2026-10-22 本机（国内家宽）直连 lrclib.net/api/get：
         单请求 5.8s；40 首串行跑 20 分钟没跑完；并发 6 → 22×RST + 18×503。
       → 端上「边播边查 LRCLIB」是不可能的（歌放完了还在转圈）。
     · 所以改成：GitHub Actions（海外）串行预取 → data/lyrics/js/ 分片 → jsDelivr
       → 端上读**静态分片**。分片已带好时间轴，零额外请求。
   分片为什么是 .js 而不是 .json：
     App 页面是 file://，这种文档下 fetch/XHR 跨源被拦死，**只放行 script/img**。
     所以产物形状是 `window.__DWG_LYRS[<i>] = {skey: {l,d,s}, ...}`，用 loadScript 直接吃。
   怎么只下 1 片而不是全量：
     清单里每片带 from/to 区间（分片按 key 排序切），端上二分一次 → 唯一一片（~1.5MB）。
   取词优先级（高→低）：
     本次会话已取(LYRLIVE.cache) → 包内快照(DB.lyr，网易云官方词) → LRCLIB 分片
       → 异步兜底（网易云 id 直播接口 → 原生桥直查 LRCLIB）。
     快排在前是因为中文歌网易云官方的词更准；LRCLIB 补的是「网易云没词/没时间轴」的那一大片。
   ===================================================================== */
const LRJS = (function(){
  const MANKEY="dwg.lyrman.v1";
  const base=()=>((typeof CDN_DYN!=="undefined"&&CDN_DYN)?CDN_DYN:CDN)+"lyrics/js/";
  let man=null, manP=null;
  const waiting={}, shardOf={}, tried={};

  function pickIdx(k){
    if(!man||!man.shards||!man.shards.length) return -1;
    let lo=0, hi=man.shards.length-1;
    while(lo<=hi){
      const mid=(lo+hi)>>1, s=man.shards[mid];
      if(!s||!s.from||!s.to) return -1;      // 老清单没区间 → 宁可不用，也别乱猜
      if(k<s.from) hi=mid-1;
      else if(k>s.to) lo=mid+1;
      else return mid;
    }
    return -1;
  }

  function loadMan(){
    if(man) return Promise.resolve(man);
    if(manP) return manP;
    /* 先用本地缓存的清单秒进（冷启动不干等网络），再后台刷一次覆盖 */
    try{ const c=localStorage.getItem(MANKEY); if(c){ const o=JSON.parse(c);
      if(o&&o.shards&&o.shards.length&&o.shards[0].from) man=o; } }catch(e){}
    manP=loadScript(base()+"m.js", 12000).then(ok=>{
      if(ok&&window.__DWG_LYRMAN&&window.__DWG_LYRMAN.shards){
        man=window.__DWG_LYRMAN;
        try{ localStorage.setItem(MANKEY, JSON.stringify(man)); }catch(e){}
      }
      return man;
    }).catch(()=>man);
    return manP;
  }

  function loadShard(i){
    if(shardOf[i]) return Promise.resolve(shardOf[i]);
    if(waiting[i]) return waiting[i];
    const sh=man&&man.shards&&man.shards[i];
    if(!sh) return Promise.resolve(null);
    waiting[i]=loadScript(base()+sh.file, 20000).then(ok=>{
      delete waiting[i];
      if(ok&&window.__DWG_LYRS&&window.__DWG_LYRS[i]){ shardOf[i]=window.__DWG_LYRS[i]; return shardOf[i]; }
      return null;                            // 三节点全失败才算失败（loadScript 内部已换节点）
    }).catch(()=>{ delete waiting[i]; return null; });
    return waiting[i];
  }

  return {
    /* 同步查已就绪的分片 —— 热路径（换歌立刻渲染）走这里，绝不阻塞 */
    peek(k){
      if(!man||!k) return null;
      const i=pickIdx(k); if(i<0) return null;
      const s=shardOf[i]; if(!s) return null;
      return s[k]||null;
    },
    /* 异步取：必要时先拉清单，再拉那一片 */
    async get(k){
      if(!k||tried[k]) return this.peek(k);
      tried[k]=1;
      await loadMan();
      const i=pickIdx(k); if(i<0) return null;
      const s=await loadShard(i);
      return (s&&s[k])||null;
    },
    /* 换歌时后台预热本片（不挡播放） */
    warm(k){
      if(!k) return;
      loadMan().then(()=>{ const i=pickIdx(k); if(i>=0) loadShard(i); }).catch(()=>{});
    },
    stats(){ return {count:man?(man.count||0):0, shards:man?(man.shards||[]).length:0,
                     loaded:Object.keys(shardOf).length}; }
  };
})();

const LY = { lines:[], idx:-1, key:"", off:0 };
function parseLRC(txt){
  const out=[];
  if(!txt) return out;
  const s=String(txt);
  /* ★ 2026-10-22：补 [offset:xxx] 支持（网易云/QQ 不少歌词带整体偏移，
     毫秒，正数=提前）。旧版直接无视 → 那种歌词从头到尾差半拍，
     用户看到的就是「歌词不同步」。 */
  let off=0;
  const mo=s.match(/\[offset:\s*([+-]?\d+)\s*\]/i);
  if(mo){ off=-parseInt(mo[1],10)/1000; }
  const re=/\[(\d{1,3}):(\d{1,2})(?:[.:](\d{1,3}))?\]/g;
  s.split(/\r?\n/).forEach(line=>{
    let m, times=[]; re.lastIndex=0;
    while((m=re.exec(line))) times.push(+m[1]*60 + +m[2] + (m[3]? parseFloat("0."+m[3]) : 0));
    const text=line.replace(re,"").replace(/\[[a-z]+:.*?\]/gi,"").trim();
    if(text) times.forEach(t=>out.push({t:Math.max(0,t+off), s:text}));
  });
  out.sort((a,b)=>a.t-b.t);
  LY.off=off;
  return out;
}
function mergeTrans(lines, transTxt){
  const tr=parseLRC(transTxt);
  if(!tr.length) return lines;
  const map={}; tr.forEach(x=>{ map[Math.round(x.t*10)]=x.s; });
  lines.forEach(l=>{ const k=Math.round(l.t*10); if(map[k]) l.tr=map[k]; });
  return lines;
}
function renderLyricIfNeeded(s){
  if(!s||!s.t) return;
  LRJS.warm(skey(s.t,s.s));              /* 后台预热本片，换歌不卡歌词 */
  const key=lyrKey(s);                   /* 与 lyricOf 同一把尺子，避免「渲染了别人版本的词」 */
  if(LY.key===key) return;
  LY.key=key; LY.idx=-1;
  const box=document.getElementById("lyrBox"); if(!box) return;
  const d=lyricOf(s);
  if(d===undefined && !LYRLIVE.tried[key]){
    // 包内没有 → 立刻去云端取一次，先显示加载态
    LY.lines=[]; box.style.transform="translateY(0)";
    box.innerHTML='<div class="lyr-empty"><div class="spin" style="margin:0 auto 10px"></div>正在取歌词…</div>';
    LYRLIVE.fetch(s);
    return;
  }
  if(!d){
    LY.lines=[]; box.style.transform="translateY(0)";
    /* 区分「取过但没有」与「取失败了」—— 后者可点重试，不让主人对着空白猜 */
    const failed = LYRLIVE.tried[key] && !LYRLIVE.cache[key] && !Native.ok;
    box.innerHTML = failed
      ? '<div class="lyr-empty">歌词没取到<br>点这里重试</div>'
      : '<div class="lyr-empty">这首歌暂无歌词<br>纯音乐或冷门曲目</div>';
    if(failed){
      box.onclick=()=>{ LYRLIVE.tried[key]=0; LY.key=""; renderLyricIfNeeded(s); };
    }
    return;
  }
  let lines=mergeTrans(parseLRC(d.l), d.t);
  LY.lines=lines;
  box.innerHTML = lines.length
    ? lines.map((l,i)=>'<div class="lyr-l" data-li="'+i+'">'+esc(l.s)+(l.tr?('<div class="lyr-tr">'+esc(l.tr)+'</div>'):"")+'</div>').join("")
    : '<div class="lyr-empty">纯音乐，请欣赏</div>';
  box.querySelectorAll("[data-li]").forEach(n=>n.onclick=()=>{
    const l=LY.lines[+n.dataset.li]; if(!l) return;
    const a=P.au(); if(a&&a.duration&&isFinite(a.duration)){ try{ a.currentTime=l.t; }catch(e){} }
    else { P.t=l.t; } syncLyric(l.t);
  });
  box.style.transform="translateY(0)";
  syncLyric(P.t);
}
/* mini 条副标题=当前歌词行（用户要求切回首页也能看见歌词）；无歌词时回落歌手名 */
function miniLyric(i){
  const el=document.getElementById("miniS"); if(!el) return;
  const l=LY.lines[i];
  let txt;
  if(l && l.s) txt="♪ "+l.s;
  else{ const s=P.cur(); txt=s?(s.s+(s.a?" · "+s.a:"")):""; }
  if(el._lt===txt) return;        // ★ 文案没变就不写 DOM（旧版每 220ms 无条件重写一次）
  el._lt=txt; el.textContent=txt;
}
function syncLyric(t){
  let i=-1;
  /* ★ 2026-10-22：+0.25s 提前量保留（人耳「看到即唱到」的观感补偿） */
  for(let k=0;k<LY.lines.length;k++){ if(LY.lines[k].t<=t+0.25) i=k; else break; }
  miniLyric(i);
  const box=document.getElementById("lyrBox");
  const pl=document.getElementById("player");
  if(!box||!pl) return;
  if(pl.dataset.view!=="lyric"||!LY.lines.length) return;
  if(i===LY.idx) return;
  LY.idx=i;
  box.querySelectorAll(".lyr-l.on,.lyr-l.near").forEach(n=>n.classList.remove("on","near"));
  const cur=box.querySelector('.lyr-l[data-li="'+i+'"]');
  if(cur){
    cur.classList.add("on");
    const pv=box.querySelector('.lyr-l[data-li="'+(i-1)+'"]'); if(pv) pv.classList.add("near");
    const nx=box.querySelector('.lyr-l[data-li="'+(i+1)+'"]'); if(nx) nx.classList.add("near");
    /* ★ 2026-10-22 修「歌词跑到屏幕偏上/大屏错位」：
       旧版写死 144px（只对 393×852 的手机大致合适），iPad 竖屏、横屏、电视上
       当前行会顶到上半屏甚至被渐隐遮住 → 看着就是「不同步」。
       现在按歌词区的真实高度算中线（0.42 略高于几何中心，读起来更顺）。 */
    const host=cur.parentElement&&cur.parentElement.parentElement;
    const h=(host&&host.clientHeight)||(pl.clientHeight*0.5)||400;
    const mid=Math.max(120, Math.round(h*0.42));
    const y=cur.offsetTop+cur.offsetHeight/2;
    box.style.transform="translateY("+(mid-y)+"px)";
  }
}
function setLyricView(on){
  const pl=document.getElementById("player"); if(!pl) return;
  const to = (on==null) ? (pl.dataset.view!=="lyric") : !!on;
  pl.dataset.view = to ? "lyric" : "cover";
  const b=document.getElementById("plActLyric"); if(b) b.classList.toggle("on", to);
  if(to){ renderLyricIfNeeded(P.cur()||{}); syncLyric(P.t); }
}

/* 评论（真数据：云端抓的网易云热评） */
function openComments(s){
  s = s || P.cur();
  if(!s){ toast("还没有播放歌曲"); return; }
  const d=cmtOf(s);
  if(!d||(!(d.hot||[]).length&&!(d.new||[]).length)){
    openSheet("评论","「"+s.t+"」",[{i:ICONS.info,l:"这首歌还没抓到评论，云端会持续补齐",fn:()=>{}}]);
    return;
  }
  const total=d.total?("共 "+plays(d.total)+" 条"):"";
  const html=(d.hot&&d.hot.length?('<div class="cmt-hd">精彩评论</div>'+d.hot.map(oneCmt).join("")):"")
            +(d.new&&d.new.length?('<div class="cmt-hd">最新评论</div>'+d.new.map(oneCmt).join("")):"");
  const sheet=document.getElementById("sheet"), body=document.getElementById("sheetB");
  document.getElementById("sheetT").textContent="评论";
  document.getElementById("sheetS").textContent=s.t+" · "+s.s+(total?" · "+total:"");
  body.innerHTML=html;
  document.getElementById("scrim").dataset.in="1"; sheet.dataset.in="1";
  Nav.overlays.push({id:"sheet", close:()=>closeSheet()});
}
function oneCmt(c){
  return '<div class="cmt"><div class="cmt-a">'+esc((c.u||"匿名").slice(0,1))+'</div>'
    +'<div class="cmt-b"><div class="cmt-u">'+esc(c.u||"匿名")+'</div>'
    +'<div class="cmt-c">'+esc(c.c||"")+'</div>'
    +'<div class="cmt-m">'+(c.d?esc(c.d):"")+(c.l?('　'+plays(c.l)+' 赞'):"")+'</div></div></div>';
}

