function openChart(name){
  const l=(DB.charts.lists||[]).find(x=>x.name===name); if(!l) return;
  const list=l.songs.map(x=>({t:x.title,s:x.singer,a:x.album,cov:x.cover,dur:durs(x.duration)}))
    .filter(x=>!isCv(x.t,x.s,x.a,x.cv) && !isJunk(x.t,x.s,x.a));                        // 榜单页默认只放原唱（搜索里翻唱仍可见、带角标）
  pushPage("chart-"+name, {
    html:`${navBar(name,`<button class="ibtn" data-listbtn aria-label="播放列表">${ICONS.list}</button>`)}
    <div style="padding:12px 0 6px">${playAllBtn(list,name)}</div>
    <div class="scroll tabbed" style="padding-top:4px"><div class="group" id="cl"></div>
      <div class="foot">共 ${list.length} 首 · 来自我们规范化的榜单数据</div></div>`,
    onMount(node){
      const box=node.querySelector("#cl");
      list.forEach((s,i)=>box.appendChild(songRow(s,i,list,name,{rank:true,sq:i%5===0})));
      node.querySelector("#playAll").onclick=()=>{P.load(list,0,name);openPlayer();};
      node.querySelector("[data-listbtn]").onclick=()=>listSheet(list,name);
      bindCommon(node);
    }
  });
}

