/* ---- 歌库 ---- */
let libSort="default";
let libCvHide=(localStorage.getItem("dwg_cvhide")||"1")==="1";   // 默认隐藏翻唱
function buildLibrary(){
  return {
    html:`${navBar("曲库",`<button class="ibtn ${libCvHide?"on":""}" data-cvf aria-label="翻唱过滤" title="${libCvHide?"已隐藏翻唱":"显示翻唱"}" style="font-size:11px;font-weight:700;letter-spacing:.5px">${libCvHide?"原唱":"全部"}</button><button class="ibtn" data-sort aria-label="排序">${ICONS.list}</button>`)}
    <div class="scroll">
      <div class="sec"><div class="searchbar"><span>${ICONS.search}</span>
        <input id="libq" placeholder="在 ${CATALOG.ready?CATALOG.fmt()+"首":"自有"}曲库里搜索" autocomplete="off"></div></div>
      <div class="sec" style="display:flex;gap:10px">
        <div class="glassbox" style="flex:1;padding:13px">
          <div style="font-size:24px;font-weight:800;letter-spacing:-.8px" id="libTot">${CATALOG.ready?CATALOG.count().toLocaleString():"载入中…"}</div>
          <div style="font-size:12px;color:var(--txt2);margin-top:3px">曲库曲目（全量）</div></div>
        <div class="glassbox" style="flex:1;padding:13px">
          <div style="font-size:24px;font-weight:800;letter-spacing:-.8px">${DB.artistList.length}</div>
          <div style="font-size:12px;color:var(--txt2);margin-top:3px">歌手</div></div>
        <div class="glassbox" style="flex:1;padding:13px">
          <div style="font-size:24px;font-weight:800;letter-spacing:-.8px">${(DB.charts.lists||[]).length}</div>
          <div style="font-size:12px;color:var(--txt2);margin-top:3px">线上榜单</div></div>
      </div>
      <div id="catWrap">
        ${(DB.cats.groups||[]).map(g=>`
          <div class="sec">
            <div class="sec-hd"><h2>${esc(g.name)}</h2><span style="font-size:12px;color:var(--txt3)">${g.count} 首</span></div>
            <div class="kw-grid">${g.cats.map(c=>`
              <div class="kwg" data-cat="${esc(g.name)}|${esc(c.name)}">${esc(c.name)}</div>`).join("")||'<span style="color:var(--txt3);font-size:13px">暂无</span>'}</div>
          </div>`).join("")||`<div class="sec"><div class="empty"><p>分类数据未加载</p></div></div>`}
      </div>
      <div class="sec" style="padding-left:16px"><div class="sec-hd" style="margin-bottom:2px"><h2>全部歌曲</h2>
        <button class="more" id="libAll">全量曲库 ›</button></div></div>
      <div id="libWrap"><div class="group" id="libList"></div></div>
      <div class="foot">分类照大牌体系：语种 / 流派 / 主题（DJ·古风·ACG）/ 心情 / 场景，点标签直达。</div>
    </div>`,
    onMount(node){
      renderLib(node);
      const q=node.querySelector("#libq");
      q.oninput=()=>renderLib(node, q.value);
      const all=node.querySelector("#libAll");
      if(all) all.onclick=()=>pushPage("catalog", buildCatalog());
      const upd=()=>{ const t=node.querySelector("#libTot");
        if(t&&CATALOG.ready){ t.textContent=CATALOG.count().toLocaleString(); q.placeholder="在 "+CATALOG.fmt()+"首曲库里搜索"; } };
      document.addEventListener("dwg:catalog", upd, {once:true});
      // 索引是分块渐进载入的：每块到位就重跑一次结果，用户能看到命中数一路上涨
      const redo=()=>{ if(!node.isConnected){ document.removeEventListener("dwg:catidx",redo); return; }
        if(node.querySelector("#libq")) renderLib(node,q.value); };
      document.addEventListener("dwg:catidx", redo);
      if(!CATALOG.ready) CATALOG.load().then(ok=>{ const t=node.querySelector("#libTot");
        if(node.isConnected&&!ok&&t) t.textContent="取不到曲库清单";
        if(ok&&node.isConnected) renderLib(node,q.value); });
      const cvf=node.querySelector("[data-cvf]");
      if(cvf) cvf.onclick=()=>{
        libCvHide=!libCvHide; localStorage.setItem("dwg_cvhide",libCvHide?"1":"0");
        cvf.classList.toggle("on",libCvHide);
        cvf.textContent=libCvHide?"原唱":"全部";
        cvf.title=libCvHide?"已隐藏翻唱":"显示翻唱";
        renderLib(node,q.value); toast(libCvHide?"已隐藏翻唱，只看原唱":"已显示全部（翻唱带角标）");
      };
      node.querySelector("[data-sort]").onclick=()=>{
        openSheet("排序方式","歌库共 "+(DB.songs||[]).length+" 首",[
          {i:ICONS.hifi,l:"默认（沉淀顺序）",on:libSort==="default",fn:()=>{libSort="default";renderLib(node,q.value);}},
          {i:ICONS.list,l:"按歌名 A→Z",on:libSort==="t",fn:()=>{libSort="t";renderLib(node,q.value);}},
          {i:ICONS.list,l:"按歌手 A→Z",on:libSort==="s",fn:()=>{libSort="s";renderLib(node,q.value);}},
          {i:ICONS.hifi,l:"仅显示有封面",on:libSort==="cov",fn:()=>{libSort="cov";renderLib(node,q.value);}}
        ],()=>renderLib(node,q.value));
      };
      bindCommon(node);
    }
  };
}
function renderLib(node,q){
  const box=node.querySelector("#libList"); if(!box) return;
  const nq=norm(q);
  let list=(DB.songs||[]).slice();
  if(nq) list=list.filter(s=>norm(s.t).includes(nq)||norm(s.s).includes(nq)||norm(s.a).includes(nq));
  let hits=null, refs=new Map();
  if(nq && !CATALOG.ready) CATALOG.load().then(ok=>{ if(ok&&node.isConnected) renderLib(node,q); });
  if(nq && CATALOG.searchReady()){             // 有关键词就把全量曲库并进来一起搜
    const seen=new Set(list.map(s=>skey(s.t,s.s)));
    hits=CATALOG.search(q,140).filter(h=>!seen.has(skey(h.t,h.s))).slice(0,80);
    list=list.concat(hits.map(h=>CATALOG.map({i:h.i,n:h.t,a:h.s,b:"",p:"",d:0,cv:h.cv,ov:h.ov,src:h.src})));
  }
  if(libCvHide) list=list.filter(s=>!isCv(s.t,s.s,s.a,s.cv) && !isJunk(s.t,s.s,s.a));   // 原唱/翻唱分离开关 + 剔视频投稿（含全量曲库结果）
  if(nq) list.sort((a,b)=>srchRank(a,nq)-srchRank(b,nq));  // 歌手本人原唱优先，翻唱/合辑靠后
  if(libSort==="t") list.sort((a,b)=>a.t.localeCompare(b.t,"zh"));
  if(libSort==="s") list.sort((a,b)=>a.s.localeCompare(b.s,"zh"));
  if(libSort==="cov") list=list.filter(s=>s.cov);
  /* ★ 2026-10-22 去重：自有歌库 + 全量曲库合并后同一首会出现两次（同名同歌手），
     排序后再去重，保证「留下来的那条」是相关度更高的那条。 */
  list=dedupeSongs(list);
  const cap=list.slice(0,300);
  box.innerHTML="";
  if(!cap.length){
    box.innerHTML=`<div class="empty"><div class="em">🔍</div><p>没有找到「${esc(q)}」</p>
      <div class="hint">${CATALOG.ready?"全量曲库 "+CATALOG.count().toLocaleString()+" 首里都没有，换个关键词试试":"正在载入全量曲库，稍后再试"}</div></div>`;
  }else{
    cap.forEach((s,i)=>box.appendChild(songRow(s,i,cap,"我的歌库",{sq:false})));
    cap.forEach((s,i)=>{ if(s.cat) box.children[i] && refs.set(s.id,{img:box.children[i].querySelector(".art"),dur:box.children[i].querySelector(".dur")}); });
    if(hits&&hits.length) CATALOG.decorate(hits,refs);
    if(list.length>cap.length){
      const m=el("div","gi",`<span class="lab" style="color:var(--txt2);font-size:14px">还有 ${list.length-cap.length} 首，输入关键词继续缩小范围</span>`);
      box.appendChild(m);
    }
  }
}

/* ---- 全部歌曲：全量曲库（10 万级）分片流式滚动 ---- */
function buildCatalog(){
  // 列表页只铺前若干页：每首歌一行，13 万行 DOM 会直接把 WebView 拖死（滚动卡、内存爆）。
  // 曲库本身仍是全量可搜的 —— 列表是"逛"，搜索是"取"。
  const PAGE_MAX=12;
  const st={n:0, list:[], busy:false, done:false};
  return {
    html:`${navBar("全部歌曲","")}
    <div class="scroll" id="cw">
      <div class="sec" style="display:flex;gap:10px">
        <div class="glassbox" style="flex:1;padding:13px">
          <div style="font-size:24px;font-weight:800;letter-spacing:-.8px" id="cTot">—</div>
          <div style="font-size:12px;color:var(--txt2);margin-top:3px">曲库曲目（热度优先）</div></div>
        <div class="glassbox" style="flex:1;padding:13px">
          <div style="font-size:24px;font-weight:800;letter-spacing:-.8px" id="cPag">0</div>
          <div style="font-size:12px;color:var(--txt2);margin-top:3px">已载入页</div></div>
      </div>
      <div class="sec"><div class="searchbar"><span>${ICONS.search}</span>
        <input id="catq" placeholder="在全量曲库里搜索" autocomplete="off"></div></div>
      <div class="group" id="cList"></div>
      <div class="foot" id="cFoot">正在准备曲库目录…</div>
    </div>`,
    onMount(node){
      const box=node.querySelector("#cList"), foot=node.querySelector("#cFoot"), sc=node.querySelector("#cw");
      const q=node.querySelector("#catq");
      let qv="";
      const paint=()=>{ node.querySelector("#cTot").textContent=CATALOG.ready?CATALOG.count().toLocaleString():"—"; };
      async function fill(){
        if(st.busy||st.done) return; st.busy=true;
        if(!CATALOG.ready){
          foot.textContent="正在载入曲库目录…";
          const ok=await CATALOG.load();
          paint();
          if(!ok){ foot.textContent="曲库目录取不到："+(CATALOG.err||"网络异常"); st.busy=false; return; }
        }
        const total=(CATALOG.man.shards||[]).length;
        if(st.n>=PAGE_MAX){
          st.done=true;
          foot.textContent="已载入 "+st.n+" 页 · "+(st.n*(CATALOG.man.shardSize||1000)).toLocaleString()
            +" 首（全库 "+CATALOG.count().toLocaleString()+" 首已全部可搜，用上面的搜索框直达任意曲目）";
          st.busy=false; return;
        }
        if(st.n>=total){ st.done=true; foot.textContent="已到底部 · 全量 "+CATALOG.count().toLocaleString()+" 首"; st.busy=false; return; }
        const arr=await CATALOG.shard(st.n);
        st.n++;
        node.querySelector("#cPag").textContent=st.n;
        if(arr) arr.forEach(rec=>{ st.list.push(CATALOG.map(rec)); box.appendChild(songRow(st.list[st.list.length-1], st.list.length-1, st.list, "全量曲库", {sq:false})); });
        foot.textContent="已载入 "+st.n+" / "+total+" 页 · 共 "+CATALOG.count().toLocaleString()+" 首（按热度+新鲜度排序），继续下滑加载";
        st.busy=false;
        if(sc.scrollTop+sc.clientHeight>sc.scrollHeight-500) fill();
      }
      sc.addEventListener("scroll",()=>{ if(sc.scrollTop+sc.clientHeight>sc.scrollHeight-600) fill(); });
      if(q) q.oninput=()=>{
        qv=q.value.trim();
        if(!qv){ box.innerHTML=""; st.list.forEach((s,i)=>box.appendChild(songRow(s,i,st.list,"全量曲库",{sq:false})));
          foot.textContent="已载入 "+st.n+" 页 · 共 "+(CATALOG.count()||0)+" 首"; return; }
        if(!CATALOG.searchReady()){ foot.textContent="搜索索引载入中 "+CATALOG.idxPct()+"%…"; CATALOG.load().then(paint); return; }
        const hits=CATALOG.search(qv,120);
        const songs=hits.map(h=>CATALOG.map({i:h.i,n:h.t,a:h.s,b:"",p:"",d:0,cv:h.cv,ov:h.ov,src:h.src}));
        box.innerHTML=""; const refs=new Map();
        songs.forEach((s,i)=>{ const row=songRow(s,i,songs,"搜索:"+qv,{sq:false,badge:"全库",badgeCls:"b-free"});
          box.appendChild(row); refs.set(s.id,{img:row.querySelector(".art"),dur:row.querySelector(".dur")}); });
        foot.textContent="命中 "+hits.length+" 首（曲库 "+CATALOG.count().toLocaleString()+" 首"
          +(CATALOG.idxDone<CATALOG.idxTotal?" · 索引 "+CATALOG.idxPct()+"%":"")+"）";
        CATALOG.decorate(hits,refs);
      };
      // 索引分块到位 → 若用户正搜着，自动补上新命中
      const reidx=()=>{ if(!node.isConnected){ document.removeEventListener("dwg:catidx",reidx); return; } if(qv) q.oninput(); };
      document.addEventListener("dwg:catidx", reidx);
      fill(); paint();
      bindCommon(node);
    }
  };
}

/* ---- 搜索（真联想 + 真历史 + 全库深度检索）---- */
const SH = {
  k:"dwg.search.h", d:[],
  load(){ try{ this.d=JSON.parse(localStorage.getItem(this.k)||"[]")||[]; }catch(e){ this.d=[]; } return this.d; },
  save(){ try{ localStorage.setItem(this.k, JSON.stringify(this.d)); }catch(e){} },
  add(q){ q=String(q||"").trim(); if(!q) return; this.d=[q].concat(this.d.filter(x=>x!==q)).slice(0,12); this.save(); },
  clear(){ this.d=[]; this.save(); }
};
SH.load();

/* 全库曲目（歌库 + 榜单 + 分类 + 主视觉 去重合并）——搜索就是真的在我们自己的全量数据里找 */
function allSongs(){
  if(DB._all) return DB._all;
  const m=new Map();
  const add=s=>{ if(!s||!s.t) return; const k=norm(s.t)+"|"+norm(s.s); if(!k||k==="|") return;
    if(!m.has(k)) m.set(k,{t:s.t,s:s.s||"",a:s.a||"",cov:s.cov||"",dur:s.dur||0}); };
  (DB.songs||[]).forEach(add);
  ((DB.charts&&DB.charts.lists)||[]).forEach(l=>(l.songs||[]).forEach(x=>add({t:x.title,s:x.singer,a:x.album,cov:x.cover,dur:durs(x.duration)})));
  (((DB.cats&&DB.cats.groups)||[])).forEach(g=>(g.cats||[]).forEach(c=>(c.songs||[]).forEach(x=>add({t:x.t,s:x.s,a:x.a,cov:x.cov,dur:durs(x.dur)}))));
  (DB.heroList||[]).forEach(add);
  DB._all=[...m.values()];
  return DB._all;
}

function buildSearch(prefill){
  const hk=(DB.charts.hotkeys||[]).slice(0,8).map(h=>h.k);
  return {
    html:`<div class="nav" style="gap:0">
      <button class="ibtn" data-back aria-label="返回">${ICONS.back}</button>
      <div style="flex:1;padding-right:8px">
        <div class="searchbar" style="margin:0;height:36px">
          <span>${ICONS.search}</span>
          <input id="sq" placeholder="歌曲、歌手、MV" autocomplete="off" value="${esc(prefill||"")}">
          <button class="ibtn" data-clear aria-label="清空" style="width:28px;height:28px">${ICONS.x.replace("18","16")}</button>
        </div>
      </div>
    </div>
    <div class="scroll" id="sw">
      <div id="sidle">
        <div class="sec" id="shistSec">
          <div class="sec-hd"><h2 style="font-size:15px;color:var(--txt2);font-weight:600">搜索历史</h2>
            <button class="more" data-hclear>清空</button></div>
          <div class="kw-wrap" style="padding:0" id="shist"></div>
        </div>
        <div class="sec"><div class="sec-hd"><h2 style="font-size:15px;color:var(--txt2);font-weight:600">热搜</h2></div>
          <div class="kw-wrap" style="padding:0">${hk.map(k=>`<div class="kw" data-kw="${esc(k)}">${esc(k)}</div>`).join("")}</div></div>
        <div class="sec"><div class="sec-hd"><h2 style="font-size:15px;color:var(--txt2);font-weight:600">试试搜 MV</h2></div>
          <div class="kw-wrap" style="padding:0">
            ${["周杰伦 MV","孤勇者 现场","五月天 演唱会","邓紫棋 MV"].map(k=>`<div class="kw" data-kw="${esc(k)}">${esc(k)}</div>`).join("")}
          </div></div>
      </div>
      <div id="ssug"></div>
      <div id="sres"></div>
    </div>`,
    onMount(node){
      const inp=node.querySelector("#sq"), res=node.querySelector("#sres"),
            sug=node.querySelector("#ssug"), idle=node.querySelector("#sidle"),
            his=node.querySelector("#shist");
      function paintHist(){
        const d=SH.d.slice(0,10);
        node.querySelector("#shistSec").style.display = d.length ? "" : "none";
        his.innerHTML = d.map(k=>`<div class="kw" data-hk="${esc(k)}">${esc(k)}</div>`).join("");
        his.querySelectorAll("[data-hk]").forEach(k=>k.onclick=()=>{ inp.value=k.dataset.hk; commit(); });
      }
      function commit(){
        const v=inp.value.trim(); if(!v) return;
        SH.add(v); paintHist();
        sug.innerHTML=""; idle.style.display="none";
        doSearch(v,res); inp.blur();
      }
      function renderSug(v){
        const nq=norm(v);
        const songs=allSongs().filter(s=>norm(s.t).includes(nq)).slice(0,6);
        const arts=DB.artistList.filter(a=>norm(a.n).includes(nq)).slice(0,4);
        let h=`<div class="sugg" data-sgo><span class="ico">${ICONS.search}</span><span style="flex:1">搜索「${esc(v)}」</span><span class="sub">回车</span></div>`;
        arts.forEach(a=>{ h+=`<div class="sugg" data-sart="${esc(a.n)}"><span class="ico">${ICONS.person}</span><span style="flex:1">${esc(a.n)}</span><span class="sub">歌手</span></div>`; });
        songs.forEach(s=>{ h+=`<div class="sugg" data-sst="${esc(s.t)}"><span class="ico">${ICONS.play}</span><span style="flex:1">${esc(s.t)}</span><span class="sub">${esc(s.s)}</span></div>`; });
        sug.innerHTML=h;
        sug.querySelector("[data-sgo]").onclick=commit;
        sug.querySelectorAll("[data-sart]").forEach(n=>n.onclick=()=>{ SH.add(n.dataset.sart); openArtist(n.dataset.sart); });
        sug.querySelectorAll("[data-sst]").forEach(n=>n.onclick=()=>{ inp.value=n.dataset.sst; commit(); });
      }
      function run(){
        const v=inp.value.trim();
        if(!v){ res.innerHTML=""; sug.innerHTML=""; idle.style.display=""; return; }
        idle.style.display="none"; res.innerHTML="";
        renderSug(v);
      }
      inp.oninput=run;
      inp.onkeydown=e=>{ if(e.key==="Enter"){ e.preventDefault(); commit(); } };
      node.querySelector("[data-clear]").onclick=()=>{ inp.value=""; run(); inp.focus(); };
      node.querySelector("[data-hclear]").onclick=()=>{ SH.clear(); paintHist(); toast("搜索历史已清空"); };
      paintHist();
      bindCommon(node);
      node.querySelectorAll("[data-kw]").forEach(k=>k.onclick=()=>{ inp.value=k.dataset.kw; commit(); });
      if(prefill) commit(); else setTimeout(()=>inp.focus(),260);
    }
  };
}
function doSearch(q, res){
  const nq=norm(q);
  if(!nq){ res.innerHTML=""; return; }
  const q2=nq.replace(/mv|现场|演唱会/g,"");
  const lib=dedupeSongs(allSongs().filter(s=>norm(s.t).includes(nq)||norm(s.s).includes(nq)||norm(s.a).includes(nq)
      || (q2 && (norm(s.t).includes(q2)||norm(s.s).includes(q2))))
    .sort((a,b)=>srchRank(a,nq)-srchRank(b,nq))).slice(0,60);
  const mvs=((DB.mv?.collections||[]).flatMap(c=>c.items)).filter(m=>norm(m.t).includes(nq)||norm(m.a).includes(nq)).slice(0,8);
  const arts=DB.artistList.filter(a=>norm(a.n).includes(nq)).slice(0,8);

  /* 全量曲库命中：与内置快照去重后追加（索引分块载入，能搜多少算多少） */
  const seen=new Set(lib.map(s=>skey(s.t,s.s)));
  const cHits=CATALOG.searchReady()? CATALOG.search(q,220).filter(h=>!seen.has(skey(h.t,h.s)))
    .sort((x,y)=>srchRank({t:x.t,s:x.s,a:"",cv:x.cv,ov:x.ov},nq)-srchRank({t:y.t,s:y.s,a:"",cv:y.cv,ov:y.ov},nq)).slice(0,80) : [];
  const cSongs=dedupeSongs(cHits.map(h=>CATALOG.map({i:h.i,n:h.t,a:h.s,b:"",p:"",d:0,cv:h.cv,ov:h.ov,src:h.src})));
  const idxFull=CATALOG.idxTotal>0 && CATALOG.idxDone>=CATALOG.idxTotal;
  let html="";
  if(arts.length){
    html+=`<div class="sec"><div class="sec-hd"><h2 style="font-size:17px">歌手</h2></div>
      <div class="rail">${arts.map(a=>`<div class="gcard round" data-artist="${esc(a.n)}" style="width:92px">
        <img class="cov" style="width:92px;height:92px" src="${esc(assetURL("av",a.n,a.av)||ph(a.n))}" alt="">
        <div class="t" style="font-size:12.5px">${esc(a.n)}</div></div>`).join("")}</div></div>`;
  }
  const allN=lib.length+cSongs.length;
  if(allN){
    html+=`<div class="sec"><div class="sec-hd"><h2 style="font-size:17px">歌曲 <span style="font-size:12.5px;color:var(--txt3);font-weight:500">命中 ${allN} 首${cSongs.length?` · 全库检索`:` · 本地缓存`}</span></h2>${cSongs.length?`<span style="font-size:12px;color:var(--txt3)">曲库 ${CATALOG.fmt()} 首</span>`:""}</div></div>
      <div class="group" id="srl"></div>`;
  }
  if(mvs.length){
    html+=`<div class="sec" style="margin-top:22px"><div class="sec-hd"><h2 style="font-size:17px">MV / 演唱会</h2></div></div>
      <div class="rail">${mvs.map(m=>`<div class="mcard" data-mv="${esc(m.id)}" style="width:190px">
        <div class="box" style="width:190px;height:107px"><img src="${esc(assetURL("cv","mv:"+m.id,m.cov)||ph(m.t))}" alt="">
        <span class="du">${fmt(durs(m.dur))}</span>${m.q?`<span class="q">${esc(m.q)}</span>`:""}</div>
        <div class="t" style="font-size:12.5px">${esc(m.t)}</div></div>`).join("")}</div>`;
  }
  if(!lib.length && !mvs.length && !arts.length){
    html=`<div class="empty"><div class="em">🎵</div><p>${idxFull?"曲库里暂时没有「"+esc(q)+"」":"正在检索全量曲库…"}</p>
      <div class="hint">${idxFull?"换个关键词试试，或按分类浏览":"搜索索引载入中 "+CATALOG.idxPct()+"%，命中会实时冒出来"}</div>
      <button class="btn btn-line" data-tolist style="margin-top:18px">${ICONS.list}<span class="btxt">去看看全部榜单</span></button>
      <button class="btn btn-line" data-tocat style="margin-top:10px">${ICONS.disc}<span class="btxt">按分类找歌</span></button></div>`;
  }
  if(!CATALOG.ready){
    html+=`<div class="sec" id="catLoad"><div class="gi"><span class="lab" style="color:var(--txt2)">
      ${CATALOG.err?("全量曲库暂时取不到（"+esc(CATALOG.err)+"），先看本地缓存结果"):"正在载入全量曲库目录…"}</span></div></div>`;
  }
  res.innerHTML=html;
  const sl=res.querySelector("#srl");
  if(sl){
    const all=lib.concat(cSongs);
    lib.forEach((s,i)=>sl.appendChild(songRow(s,i,all,"搜索:"+q,{sq:false})));
    const refs=new Map();
    cSongs.forEach((s,i)=>{
      const row=songRow(s,lib.length+i,all,"搜索:"+q,{sq:false,badge:"全库",badgeCls:"b-free"});
      sl.appendChild(row);
      refs.set(s.id,{img:row.querySelector(".art"),dur:row.querySelector(".dur")});
    });
    if(cHits.length) CATALOG.decorate(cHits,refs);   // 补封面/时长（按需拉分片）
  }
  if(!CATALOG.ready && !CATALOG.loading){
    CATALOG.load().then(ok=>{ if(res.isConnected){ if(ok) doSearch(q,res); else { const n=res.querySelector("#catLoad"); if(n) n.innerHTML=`<div class="gi"><span class="lab" style="color:var(--txt2)">全量曲库取不到：${esc(CATALOG.err)}</span></div>`; } } });
  }
  // 索引每到位一块就重跑本页 → 命中数实时长出来（页面离开即自动摘掉监听）
  if(!idxFull){
    const reidx=()=>{ if(!res.isConnected){ document.removeEventListener("dwg:catidx",reidx); return; } doSearch(q,res); };
    document.addEventListener("dwg:catidx", reidx);
  }
  const tl=res.querySelector("[data-tolist]");
  if(tl) tl.onclick=()=>{ while(Nav.stack.length>1) popPage(); gotoTab("charts"); };
  const tc=res.querySelector("[data-tocat]");
  if(tc) tc.onclick=()=>pushPage("library", buildLibrary());
  bindCommon(res);
}

/* ---- 歌手页 ---- */
function openArtist(name){
  const a=DB.artistList.find(x=>x.n===name)||{n:name,seen:0};
  const songs=(DB.songs||[]).filter(s=>norm(s.s).includes(norm(name))).slice(0,60);
  const mvs=((DB.mv?.collections||[]).flatMap(c=>c.items)).filter(m=>norm(m.a).includes(norm(name))||norm(m.t).includes(norm(name))).slice(0,8);
  pushPage("artist-"+name,{
    html:`<div class="nav" style="border:0;background:transparent;position:absolute;width:100%">
      <button class="ibtn" data-back aria-label="返回" style="background:rgba(0,0,0,.4);backdrop-filter:blur(12px)">${ICONS.back}</button>
      <h1></h1><div class="nav-right"><span class="spacer"></span></div></div>
    <div class="scroll">
      <div style="height:236px;position:relative;display:flex;align-items:flex-end;padding:0 0 16px">
        <div style="position:absolute;inset:0;background:linear-gradient(180deg,var(--accent-soft),transparent 70%)"></div>
        <div style="position:relative;display:flex;align-items:center;gap:14px;padding:0 20px;width:100%">
          <img src="${esc(assetURL("av",name,a.av)||ph(name))}" style="width:96px;height:96px;border-radius:50%;object-fit:cover;box-shadow:0 14px 34px -12px rgba(0,0,0,.9)" alt="">
          <div style="min-width:0">
            <div style="font-size:26px;font-weight:800;letter-spacing:-.7px">${esc(a.n)}</div>
            <div style="font-size:13px;color:var(--txt2);margin-top:5px">${a.seen||0} 首在库 · ${songs.length} 首可播</div>
          </div>
        </div>
      </div>
      <div style="padding:0 0 8px">${playAllBtn(songs.length?songs:[{t:a.n,s:"—",cov:a.av,dur:0}],a.n)}</div>
      ${mvs.length?`<div class="sec"><div class="sec-hd"><h2 style="font-size:17px">MV / 现场</h2></div></div>
      <div class="rail">${mvs.map(m=>`<div class="mcard" data-mv="${esc(m.id)}" style="width:190px">
        <div class="box" style="width:190px;height:107px"><img src="${esc(assetURL("cv","mv:"+m.id,m.cov)||ph(m.t))}" alt="">
        <span class="du">${fmt(durs(m.dur))}</span>${m.q?`<span class="q">${esc(m.q)}</span>`:""}</div>
        <div class="t" style="font-size:12.5px">${esc(m.t)}</div></div>`).join("")}</div>`:""}
      <div class="sec"><div class="sec-hd"><h2 style="font-size:17px">歌曲</h2></div></div>
      <div class="group" id="al"></div>
      <div class="foot">头像来自我们的歌手头像库（每 2 小时刷新）</div>
    </div>`,
    onMount(node){
      const box=node.querySelector("#al");
      const list=songs.length?songs:[{t:"暂无该歌手曲目",s:name,cov:a.av,dur:0}];
      list.forEach((s,i)=>box.appendChild(songRow(s,i,list,a.n)));
      node.querySelector("#playAll").onclick=()=>{P.load(list,0,a.n);openPlayer();};
      bindCommon(node);
    }
  });
}

/* ---- 我的（本地真持久化：收藏 / 最近播放 / 下载）---- */
