function listSheet(list,ctx){
  /* 队列 = 三横杆：当前曲高亮，点谁放谁（列表不变、只跳位次，避免重建队列打乱收藏语境） */
  openSheet("当前播放", (ctx||P.ctx)+" · "+list.length+" 首", list.slice(0,60).map((s,i)=>({
    i:String(i+1).padStart(2,"0"), l:s.t, sub:s.s, on:i===P.i,
    fn:()=>{ if(i===P.i){ openPlayer(); return; }
             if(list===P.queue){ P.i=i; P.start(true); } else { P.load(list,i,ctx); }
             openPlayer(); }
  })));
}

