document.addEventListener("keydown",e=>{
  if(e.key==="Escape"){ e.preventDefault(); back(); }
  else if(e.key===" "&&P.cur()){ e.preventDefault(); P.toggle(); }
  else if(e.key==="ArrowRight"&&P.cur()){ P.next(1); }
  else if(e.key==="ArrowLeft"&&P.cur()){ P.next(-1); }
});
